  'admin.settings.usageTelemetryHelp': "수집의 마스터 스위치입니다. 켜면 앱은 어떤 도구를 사용하는지와 해석이 어떻게 끝나는지를 보내며 모델의 내용은 절대 보내지 않습니다. 대상은 끄지 않은 모든 사용자입니다. 약관에 설명된 대로 기본적으로 허용되며, 각자 설정이나 프로필에서 끌 수 있습니다. 끄면 아무도 아무것도 보내지 않으며 지표에는 방문과 사용이 집계되지 않습니다. 계정 수치는 이 설정과 무관합니다. 로그인 여부와도 무관합니다.",
