  'landing.pricingH': "오픈 프로젝트를 지속하기 위한 계획",
  'landing.pricingP': "브라우저에서 구조 해석을 하는 핵심 프로그램은 오픈 소스이며 모든 사용자에게 무료입니다. 일부 전문 모듈은 유료이며, 대학에는 해당 모듈이 무료로 제공됩니다. Stabileo AI와 대용량 클라우드 연산은 대학을 포함한 모든 사용자가 비용을 부담하며, 실제 소요 비용을 충당하는 수준으로 책정됩니다.",
  'landing.pricingCommunity': "저장소는 공개되어 있습니다. 기여, 버그 보고, 설계 논의를 환영합니다.",
  'landing.figTitle': "여섯 패널 Pratt 데크 트러스 위를 이동하는 단위 하중",
  'landing.figDesc': "여섯 패널 Pratt 트러스, 왼쪽은 힌지 지점, 오른쪽은 롤러 지점. 아래 방향 단위 하중이 데크를 가로지릅니다. 부재는 축력을 나타내며 빨강은 인장, 파랑은 압축, 회색은 영에 가까운 값입니다. 처짐은 정규화되어 있습니다.",
  'landing.heroFigTruss': "트러스",
  'landing.heroFigMohr': "응력 해석",
  'landing.mohrFigTitle': "3D 응력 상태를 가로지르는 절단면",
  'landing.mohrFigDesc': "회전하는 절단면이 있는 응력 큐브와, 오른쪽에 세 개의 Mohr 원 및 그 절단면의 점 (σn, τ)이 있습니다. 이 점은 절단면이 z축을 중심으로 회전하는 동안 σ₁–σ₂ 원을 따라 움직이고, 절단면이 기울어지면 원들 사이의 영역으로 이동합니다. 빨강은 인장, 파랑은 압축, 노랑은 전단입니다.",
  'landing.figZero': "영에 가까움  ≈0",
  'landing.figDeformedNorm': "변형 형상 · 정규화",
  'landing.trussTag': "BASIC 모드 · 실시간",
  'landing.trussTension': "인장",
  'landing.trussTMax': "T 최대",
  'landing.trussCompression': "압축",
  'landing.trussCMax': "C 최대",
  'landing.mohrTag': "도구 · MOHR 3D",
  'landing.heroFigBuilding': "건물",
  'landing.heroFigSection': "단면 해석",
  'landing.heroFigResearch': "연구용 모델",
  'landing.heroFigModal': "진동 모드",
  'landing.heroFigShed': "공장 건물",
  'landing.shedTitle': "PRO 예제 공장 건물의 Von Mises 응력",
  'landing.shedDesc': "PRO 예제의 강구조 공장 건물로, 트러스 골조, 퍼린, 가새로 이루어져 있습니다. 카메라가 회전하는 동안 각 부재는 7개 조합에서의 최대 Von Mises 응력에 따라 파랑(낮음)에서 빨강(fy에 도달)까지 색이 입혀집니다.",
  'landing.shedTag': "PRO 모드 · A36 강재",
  'landing.shedHeading': "부재별 응력",
  'landing.bldTitle': "PRO 예제의 7층 건물을 부재 하나씩 조립하는 모습",
  'landing.bldDesc': "PRO 예제의 7층 H-30 콘크리트 건물입니다. 기둥, 코어 벽체, 보, 슬래브가 층별로 들어가며, 들어가는 부재는 빨간색으로 표시되고 카메라가 천천히 회전합니다. 완성되면 조합 U2의 결과를 보여 줍니다. 먼저 파란색으로 축력을, 이어서 보의 휨모멘트도를 표시합니다.",
  'landing.bldTag': "PRO 모드 · H-30 콘크리트",
  'landing.bldFloor': "층",
  'landing.bldGoverningN': "지배 N",
  'landing.heroFigCompression': "압축",
  'landing.heroFigTension': "인장",
  'landing.heroFigZero': "영",
  'landing.bldMoment': "휨모멘트",
  'landing.bldMMax': "M 최대",
  'landing.secTitle': "골조의 보를 따라 이동하는 Basic 모드 단면 해석",
  'landing.secDesc': "골조의 보를 따라 단면이 이동합니다. 옆에는 20 × 50 cm 직사각형 단면과 해칭된 수직응력 분포가 표시되며, 파랑은 압축, 빨강은 인장입니다. 단면의 핵 NC는 형상에 의해 고정됩니다. 중립축 EN과 압력 중심 CP는 보를 따라 휨모멘트가 변함에 따라 이동합니다.",
  'landing.secTag': "BASIC 모드",
  'landing.secOut': "화면 밖",
  'landing.topTitle': "Stabileo Research에서 재현한 Andreassen 등(2011)의 위상 최적화",
  'landing.topDesc': "Andreassen 등(2011)의 논문에 나오는 MBB 보로, 60 × 20 요소 반쪽을 대칭으로 복제한 것입니다. 하중 아래의 처짐이 최소가 될 때까지 반복마다 재료가 재분배됩니다. 반복 결과는 Stabileo Research 최적화기에서 나온 것이며, 저자들의 코드와 대조하여 검증했습니다.",
