  'landing.reload': "다시 시도",
  'landing.navResearch': "연구",
  'landing.ebHero': "무료 오픈 소스 · 구조 해석",
  'landing.heroH': "검증할 수 있는 구조 해석.",
  'landing.heroP': "2D와 3D 골조 및 트러스를 내 컴퓨터에서 해석하고, 다른 일곱 개 유한요소 프로그램과 대조하여 검증했습니다. 아직 개발 중인 AI 어시스턴트는 이미 같은 모델과 해석기에서 작동하며, 본인의 Claude 또는 OpenAI 키를 사용합니다.",
  'landing.heroCtaPrimary': "편집기 열기",
  'landing.heroBlogLink': "블로그 읽기",
  'landing.heroMetaA': "최신 브라우저 어디서나 작동",
  'landing.heroMetaB': "오픈 소스",
  'landing.heroMetaC': "아르헨티나 제작 · FIUBA · Ergodic Group",
  'landing.fitH': "Stabileo의 위치",
  'landing.fitDeskH': "상용 데스크톱 패키지",
  'landing.fitDeskP': "SAP2000, ETABS, Robot, STAAD.Pro: 비공개 소스이며 설치해서 사용하고, 훨씬 더 많은 설계 기준을 지원하며 수십 년간 사용되어 왔습니다. Stabileo는 오픈 소스이며 브라우저에서 실행됩니다.",
  'landing.fitScriptH': "오픈 소스 해석기",
  'landing.fitScriptP': "OpenSees, Code_Aster, CalculiX: 공개되어 있고 강력하지만 스크립트나 입력 파일로 실행합니다. Stabileo는 시각적이며, 우리는 이 세 가지 모두와 해석기를 비교합니다.",
  'landing.fitClassH': "교육용 소프트웨어",
  'landing.fitClassP': "토목공학 강의에서 흔히 쓰는 Ftool은 평면 골조를 해석합니다. Stabileo는 3D를 추가하고 각 결과의 계산 과정을 보여 줍니다.",
  'landing.modBasic': "Basic",
  'landing.modProCalc': "PRO · 해석",
