  'landing.priceFree': "무료",
  'landing.ebBasic': "BASIC",
  'landing.badgeFreeAlways': "언제나 무료",
  'landing.basicH': "토목공학을 위한 오픈 소스 포켓 계산기.",
  'landing.basicP': "2D와 3D에서 모델링하고, 하중을 가하고, 해석하고, 결과를 읽습니다. 답만이 아니라 계산 과정을 보여 줍니다.",
  'landing.basicPt1': "실시간 계산: 절점을 끌거나 하중을 바꾸면 결과가 즉시 갱신됩니다.",
  'landing.basicPt2': "강성법의 단계별 풀이: 요소 행렬, 조립, 해.",
  'landing.basicPt3': "운동학적 해석(2D)은 개수 공식이 놓치는 경우까지 포함하여 메커니즘을 찾아냅니다.",
  'landing.basicPt4': "단면 해석은 중실 단면, Bredt, Saint-Venant 중 어떤 비틀림 이론이 적용되는지 알려 줍니다.",
  'landing.basicPt5': "2D와 3D에서 P-Δ, 좌굴, 고유치 해석을 제공하며, 2D에서는 소성 붕괴와 영향선도 제공합니다.",
  'landing.ebProCalc': "PRO · 해석",
  'landing.proCalcH': "유한요소와 복잡한 모델.",
  'landing.proCalcP': "슬래브와 벽체, 단계별 시공, 비선형 및 동적 해석을 Basic과 동일한 검증된 해석기로 제공합니다.",
  'landing.ebProDesign': "PRO · 설계",
  'landing.proDesignH': "기준 검토와 부재 설계.",
  'landing.proDesignP': "부재를 검토하고 설계합니다. 콘크리트는 CIRSOC 201, 강재는 CIRSOC 301(실험적), 하중과 조합은 CIRSOC 101–104에 따릅니다. AISC 360, EN 1993-1-1, AISI S100, ACI 318, EN 1992-1-1에 따른 실험적 검토는 일부 단면에 한정됩니다.",
  'landing.metaDescription': "브라우저에서 사용하는 무료 오픈 소스: 2D 및 3D 골조와 트러스. CIRSOC 201 설계와 실험적 AISC, ACI, Eurocode 검토는 유료이며 대학에는 무료입니다. AI 어시스턴트 개발 중.",
  'landing.metaTitle': "Stabileo — 오픈 소스 구조공학 소프트웨어, AI 개발 중",
  'landing.proDesignCirsocLink': "현재 CIRSOC 기준으로 검토하는 항목",
  'landing.proDesignRoadmapLink': "남은 3D 설계 작업",
  'landing.ebVerif': "검증",
  'landing.verifH': "결과를 검증하는 방법과 검증의 한계.",
  'landing.verifP': "해석기는 사용자의 컴퓨터에서 실행됩니다. 일곱 개 유한요소 프로그램 및 공개된 결과와 비교하고 물리적 불변량을 시험합니다. 가능한 경우 인증서도 계산합니다. 이는 수치 오차의 한계이며, 선형, 고유치, 소성 붕괴 해석에 대해 그 핵심 수학을 Lean으로 증명했습니다. 이 한계는 조립된 시스템을 푸는 과정만 다루며, 모델이 옳은지는 다루지 않습니다. 사용 중 결과에 영향을 주었을 수 있는 결함은 공지로 게시합니다.",
