  'advHelp.fm.label': "단계별 — 유연도법(응력법)",
  'advHelp.fm.text': "응력법으로 구조물을 한 단계씩 해석합니다. 부정정 차수, 잉여력과 기본 구조의 선택, 0 상태와 단위 상태 및 그 휨모멘트도, Mohr 적분에 의한 유연도 계수 δij와 하중항 δi0, 적합 방정식, 중첩, 그리고 강성법과의 최종 대조를 다룹니다. 2D와 3D의 골조와 트러스를 지원합니다.",
  'fm.wizardTitle': "단계별 — 유연도법",
  'fm.step1Name': "부정정 차수",
  'fm.step2Name': "기본 구조와 잉여력",
  'fm.step3Name': "0 상태: 기본 구조에 작용하는 하중",
  'fm.step4Name': "단위 상태 Xi = 1",
  'fm.step5Name': "유연도 계수 δij",
  'fm.step6Name': "하중항 δi0",
  'fm.step7Name': "적합 방정식",
  'fm.step8Name': "중첩",
  'fm.step9Name': "강성법과의 대조",
  'fm.banner': "2D · 골조와 트러스 · Euler–Bernoulli 부재 (전단 변형 무시)",
  'fm.s1.explanation': "정역학 평형 방정식만으로는 모든 힘을 구할 수 없는 구조물을 <strong>부정정</strong> 구조물이라고 합니다. <strong>부정정 차수</strong> GH는 남는 힘의 수를 나타내며, GH = 미지수 − 방정식입니다.",
  'fm.s1.reactions': "지점 반력 (r)",
  'fm.s1.springs': "스프링 힘",
  'fm.s1.bars': "부재의 미지 힘",
  'fm.s1.barsNote': "골조 부재는 3개를 더하며(한 단부의 N, V, M이며 다른 단부는 부재 자체의 평형에서 정해집니다), 힌지 단부 하나마다 하나씩 줄어듭니다. 트러스 부재는 1개(N)를 더합니다.",
  'fm.s1.equations': "평형 방정식",
  'fm.s1.equationsNote': "절점마다 2개(ΣFx = 0, ΣFz = 0)에, 모멘트가 존재할 수 있는 곳(강접된 부재 단부 또는 회전을 구속하는 지점)마다 ΣM = 0을 더합니다.",
  'fm.s1.hyper': "힘이 {gh}개 더 많습니다. 이 방법은 부족한 방정식 {gh}개를 변형 적합 조건에서 찾습니다.",
  'fm.s1.iso': "GH = 0: 구조물은 정정입니다. 정역학만으로 충분하여 이 방법에는 미지수가 없습니다. 그래도 단계를 따라가며 각 단계에서 그것이 무엇을 뜻하는지 확인할 수 있습니다.",
  'fm.iso.s2': "GH = 0이면 해제할 것이 없습니다. 기본 구조가 곧 구조물 자체입니다.",
  'fm.iso.s3': "0 상태가 이미 답입니다. 구조물이 정정이므로 실제 하중을 가하면 최종 다이어그램이 바로 나옵니다.",
  'fm.iso.none': "이 단계에서 할 일이 없습니다. 잉여력이 없으므로 단위 상태, 유연도 계수, 적합 방정식도 없습니다. 평형만으로 0 상태에서 답이 나왔습니다.",
  'fm.iso.s8': "M = M₀: 잉여력이 없으므로 중첩할 것이 없습니다.",
  'fm.s2.explanation': "GH개의 힘을 선택하여(<strong>잉여력</strong> X₁…Xₙ) 제거합니다. 남은 것이 <strong>기본 구조</strong>이며 정정이고 안정합니다. 그런 다음 Xᵢ를 기본 구조에 작용하는 미지 하중으로 취급합니다.",
  'fm.s2.original': "실제 구조물",
  'fm.s2.primary': "잉여력을 하중으로 나타낸 기본 구조",
  'fm.s2.list': "선택한 잉여력",
  'fm.s2.why': "선택 순서: 먼저 고정단 모멘트, 다음에 내부 지점의 반력, 그다음 트러스 부재이며, 닫힌 고리를 열어야 하면 부재 하나를 절단합니다. 이렇게 얻은 기본 구조가 안정함을 확인했습니다.",
  'fm.s2.prescribed': "이 지점에는 강제 변위 Δ = {d} m가 있습니다. 이는 해당 적합 방정식의 우변으로 갑니다.",
