  'ex.tower3D_2': "2층 타워",
  'ex.tower3D_2.desc': "6m 가새 타워, 기둥 4개",
  'ex.tower3D_4': "4층 타워",
  'ex.tower3D_4.desc': "테이퍼가 있는 12m 가새 타워",
  'ex.3d-nave-industrial': "공장 건물",
  'ex.3d-nave-industrial.desc': "래티스 기둥과 지붕 트러스, 퍼린, 가새, 천장 크레인이 있는 주행 보로 이루어진 강구조 건물.",
  'ex.3d-building': "슬래브 없는 5층 철근콘크리트 골조",
  'ex.3d-building.desc': "부재만으로 이루어진 5층 콘크리트 건물로, 고정하중, 활하중, 풍하중, 지진하중이 있습니다.",
  'ex.pro-edificio-7p': "7층 철근콘크리트 건물",
  'ex.pro-edificio-7p.desc': "승강기와 계단이 있는 공동주택: 슬래브와 벽체는 쉘로, 층마다 강체 다이어프램, 풍하중과 용도별 하중.",
  'ex.rc-qa-diagnostic': "풍하중과 지진하중을 받는 소형 철근콘크리트 골조",
  'ex.rc-qa-diagnostic.desc': "양방향 풍하중과 지진하중을 받는 2층 콘크리트 골조로, 각 케이스마다 고유한 부호를 가집니다.",
  'ex.rc-qa-diagnostic-shells': "철근콘크리트 QA 진단 쉘 (PRO)",
  'ex.rc-qa-diagnostic-shells.desc': "보/기둥 위의 철근콘크리트 슬래브(휨)와 벽체(막) 및 곡선 보 — 모든 쉘 등고선 성분이 어딘가에서 변합니다",
  'pro.tagCad': "CAD 초안",
  'ex.cad-arch-structure-dxf.purpose': "CAD / 초안 / 가정",
  'ex.cad-arch-only-dxf.purpose': "CAD / 제안 / 가정",
  'ex.cad-arch-structure-dxf': "DXF에서: 건축과 구조",
  'ex.cad-arch-structure-dxf.desc': "주석이 달린 구조 평면이 있는 DXF에서 생성한 10층 콘크리트 초안으로, 가정이 기록되어 있습니다.",
  'ex.cad-arch-only-dxf': "DXF에서: 건축만",
  'ex.cad-arch-only-dxf.desc': "건축만 있는 DXF에서 제안한 10층 초안으로, 모든 부재가 가정입니다.",
  'ex.pro-edificio-7p.purpose': "철근콘크리트 / 쉘 / 기준",
  'ex.3d-nave-industrial.purpose': "강재 / 크레인 / 접합부",
  'ex.rc-qa-diagnostic.purpose': "철근콘크리트 / 조합 / 방향",
  'pro.examples.groupBuildings': "건물",
  'pro.examples.groupFoundations': "기초",
  'pro.examples.groupLongSpan': "교량과 장경간",
  'pro.examples.groupIndustrial': "산업 시설",
  'pro.examples.groupEnergy': "에너지 및 해양",
  'pro.examples.groupXL': "XL 쇼케이스",
  'pro.examples.groupValidation': "검증 모델",
  'ex.validation-01': "검증 01 · 슬래브가 있는 강구조 건물",
  'ex.validation-01.desc': "강재 골조와 콘크리트 슬래브, 쉘로 메쉬한 코어 벽체로 이루어진 3층 건물로, 공개된 구조물을 번호와 메쉬까지 1:1로 모델링했습니다. 보는 단부 오프셋만큼 슬래브 중간면 아래에 놓이며, 슬래브 압력은 면하중입니다.",
  'ex.validation-01.purpose': "검증 / 슬래브 / 오프셋",
  'pro.tagValidation': "검증",
  'ex.validation-06': "검증 06 · 횡력을 받는 평면 골조",
  'ex.validation-06.desc': "공개된 구조물을 번호까지 1:1로 모델링한 2경간 5층 강재 골조입니다. 원본 프로그램이 생성한 지진력은 절점 하중으로 가했고, 질량만 만든 두 개의 중력 케이스는 일반 케이스로 유지했습니다. 단면은 성질로 주어지며 전단 변형을 포함합니다.",
  'ex.validation-06.purpose': "검증 / 지진 / 전단",
  'ex.validation-02': "검증 02 · 트러스가 있는 경량 창고",
  'ex.validation-02.desc': "경사 트러스 문형 골조 3개, 퍼린, 가새 트러스로 이루어진 강구조 창고로, 공개된 구조물을 번호까지 1:1로 모델링했습니다. 강접 접합, 전체 단부 오프셋, 퍼린의 롤 각도는 원본과 같고, 현재 하중은 전체 좌표축과 국부 좌표축으로 가했습니다.",
  'ex.validation-02.purpose': "검증 / 트러스 / 오프셋",
  'ex.validation-03': "검증 03 · 벽체가 있는 창고",
  'ex.validation-03.desc': "사변형 쉘로 메쉬한 콘크리트 벽체 2개가 트러스 4개와 길이 방향 채널 5개로 이루어진 강재 지붕을 지지하는 창고로, 공개된 구조물을 번호와 메쉬까지 1:1로 모델링했습니다. 앵글은 주축을 기준으로 주어지며 각 부재의 롤은 원본과 같습니다.",
  'ex.validation-03.purpose': "검증 / 벽체 / 쉘",
  'ex.validation-04': "검증 04 · 크레인 주행로가 있는 산업용 격납고",
  'ex.validation-04.desc': "지붕 트러스, 출입문, 부속 건물, 크레인 주행로, 배관 랙이 있는 강구조 격납고로, 공개된 구조물을 번호까지 1:1로 모델링했습니다. 부재 2482개 중 다수가 단부 힌지이며 하중 케이스는 22개입니다. 케이스는 선형으로 해석하고 각 조합은 계수 하중에 대한 P-Delta로 해석하며, 원본은 케이스도 P-Delta로 해석합니다. 원본의 부재 기준 검토는 재현하지 않습니다. 안정한 2차 평형이 없는 조합은 부재력을 게시하지 않고 목록으로만 표시합니다.",
  'ex.validation-04.purpose': "검증 / P-Delta / 해제",
  'ex.validation-05': "검증 05 · 지선 타워",
  'ex.validation-05.desc': "지선 18개로 앵커 3곳에 고정된 높이 57.6 m의 삼각형 래티스 타워로, 공개된 구조물을 번호까지 1:1로 모델링했습니다. 지선은 인장에만 작용하며 조합은 케이스의 합입니다. 원본과 같이 각 조합이 고유한 활성 집합을 가지며, 풍하중은 지선에도 작용합니다.",
  'ex.validation-05.purpose': "검증 / 인장 전용 / 중첩",
  'ex.validation-07': "검증 07 · 바닥 하중이 있는 건물",
  'ex.validation-07.desc': "불규칙한 평면의 4층 콘크리트 건물로, 공개된 구조물을 번호까지 1:1로 모델링했습니다. 바닥 하중은 이미 사다리꼴로 보에 분배되어 각 부재에서 끊기며, 각 층은 강체 다이어프램이고 자중은 고정하중 케이스에 있습니다.",
  'ex.validation-07.purpose': "검증 / 바닥 / 다이어프램",
  'pro.tagRC': "철근콘크리트",
  'pro.tagDrift': "층간변위",
