  'project.export': "내보내기",
  'project.importHelp': "모델을 스프레드시트의 모델로 교체합니다. 먼저 템플릿을 내려받으십시오. 템플릿에는 시트, 열, 각각의 예시가 들어 있으며, 이 가져오기 기능이 읽는 유일한 Excel 형식입니다. .ded를 열려면 위의 열기를 사용하십시오. DXF와 IFC는 PRO에 있습니다.",
  'project.exportViewHelp': "보고서나 시험에 쓸 그림입니다. 구조물, 다이어그램, 평형을 이룬 자유물체를 흰 배경에 깔끔하게 그립니다. 형식은 대화 상자에서 선택하며 SVG(벡터, 편집 또는 인쇄용), PNG, JPG가 있습니다. 문서에 바로 복사하여 붙여 넣을 수도 있습니다.",
  'project.exportReportHelp': "제출용 문서입니다. 담을 내용을 선택합니다. 모델 데이터, 하중, 운동학적 해석, 평형을 이룬 자유물체, 그리고 각 결과를 표, 다이어그램 또는 둘 다로 선택하며, PDF, Word 또는 HTML 형식을 선택합니다.",
  'project.exportResultsHelp': "계속 작업할 수 있는 수치입니다. Excel: 모델과 결과(요약, 부재, 절점, 반력, 재료, 단면, 쉘, 조합)를 시트 하나씩 담은 통합 문서입니다. CSV: 결과 표만 담습니다. 모델을 해석하지 않았다면 내보내기 시 해석합니다. 둘 다 여기로 다시 가져올 수 없습니다. 가져오기에는 템플릿을 사용하며, 템플릿은 다른 시트를 사용합니다.",
