  'flex.out.ok': "만족",
  'flex.out.notOk': "불만족",
  'flex.out.memo': "계산 과정",
  'flex.out.sectionTooSmall': "철근비 8 %에서도 단면이 만족하지 않습니다",
  'flex.out.checkInputs': "입력값을 확인하십시오",
  'flex.scope': "시트 여덟 개 전체를 셀 단위로 비교했으며, 복철근 블록, 여섯 개의 특성점, 그리고 그려진 상관 계열을 포함합니다. 명시된 차이는 다음과 같습니다. 원형 단면은 통합 문서보다 약 0.6 % 가볍게 나옵니다. 2축 상관 곡면의 단면은 사분면 중간에서 최대 0.6 % 더 큰데, 통합 문서가 압축 영역을 이산화하기 때문입니다. 원형 시트에서 축력 한계의 모멘트는 통합 문서 자체 격자의 간격을 가로지르는 직선 현이어서 곡선을 4.4 % 과대평가하며, 여기서는 곡선 위의 점을 사용합니다. 그리고 철근이 한 단에 들어가지 않게 되면 여기서는 철근을 쌓아 d를 철근군의 도심까지로 잡으므로, 항상 한 단만 가정하는 통합 문서보다 더 많은 철근을 요구합니다. 2005년 이후 판에서는 결과가 다를 수 있으며 통합 문서와 대조하지 않았습니다.",
  'flex.attribution': "CIRSOC 201-2005 조항. 자체 구현이며 INTI-CIRSOC의 CIRSOC_FLEX 통합 문서(D. A. Ortega) 결과와 대조하여 시험했습니다.",
  'flex.scopeSummary': "CIRSOC_FLEX와 대조한 항목",
