  'status.grid': "격자",
  'whatsNew.title': "Stabileo {version}: 결과가 달라질 수 있습니다",
  'whatsNew.body': "이 버전은 설계 검토(3D CIRSOC 201 기둥, EN 1992 휨, CIRSOC 301 압축, 최소 압축 상태의 철근콘크리트 기둥), 하중 생성기, 좌굴, 조화 해석 및 시간이력해석, 3D에서 2D로의 절단, 쉘 조합 응력에서 발견된 잘못된 결과를 수정합니다. 각 수정에는 안전 공지(SA-2026-025부터 047까지)가 있습니다. 일부 모델은 이제 조용히 해석되는 대신 거부되거나 표시됩니다. 2D 소성 붕괴는 수정이 반영될 때까지 계속 거부됩니다. 이전 결과를 신뢰하기 전에 프로젝트를 다시 해석하고 설계 검토를 확인하십시오.",
