  'tooltip.toolSelect.title': "선택 (V)",
  'tooltip.toolSelect.desc': "5가지 하위 모드가 있습니다: 절점, 부재, 지점, 하중, 응력. 플로팅 바에서 전환합니다.",
  'tooltip.toolNode.title': "절점 생성 (N)",
  'tooltip.toolNode.desc': "캔버스를 클릭하여 접합점을 놓습니다. 절점은 부재가 연결되고 하중이 작용하는 곳입니다.",
  'tooltip.toolElement.title': "부재 생성 (E)",
  'tooltip.toolElement.desc': "시작 절점을 클릭한 다음 끝 절점을 클릭합니다. 두 절점 사이에 부재가 생성됩니다. 골조 = 강접합, 트러스 = 핀 접합.",
  'tooltip.toolSupport.title': "지점 생성 (S)",
  'tooltip.toolSupport.desc': "절점을 클릭하여 지점을 놓습니다. 지점 유형에 따라 구속되는 움직임이 정해집니다.",
  'tooltip.toolLoad.title': "하중 적용 (L)",
  'tooltip.toolLoad.desc': "절점(집중하중) 또는 부재(분포하중)를 클릭하여 힘을 적용합니다. 음수 값 = 아래 방향.",
  'tooltip.toolInfluence.title': "영향선 (I)",
  'tooltip.toolInfluence.desc': "단위 하중이 구조물을 가로지를 때 반력이나 부재력이 어떻게 변하는지 보여 줍니다.",
  'tooltip.toolPan.title': "화면 이동 (H)",
  'tooltip.toolPan.desc': "드래그하여 화면을 이동합니다. 마우스 가운데 버튼 클릭 또는 Ctrl+드래그도 사용할 수 있습니다.",
  'tooltip.solve.title': "해석",
  'tooltip.solve.desc': "직접강성법(DSM)으로 구조물을 해석합니다. 절점, 부재, 지점, 하중이 필요합니다.",
  'tooltip.selfweight.title': "자중",
  'tooltip.selfweight.desc': "재료 밀도와 단면적을 사용하여 중력 분포하중을 자동으로 추가합니다.",
  'tooltip.diagNone.title': "선도 없음",
  'tooltip.diagNone.desc': "모든 결과 선도를 숨깁니다. 구조물만 표시됩니다.",
  'tooltip.diagDeformed.title': "변형 형상",
  'tooltip.diagDeformed.desc': "확대한 변형 형상을 표시합니다. 거동이 타당한지 확인하는 데 유용합니다.",
  'tooltip.diagMoment.title': "휨모멘트 (M)",
  'tooltip.diagMoment.desc': "각 부재의 휨모멘트도. 관례에 따라 인장측에 그립니다.",
  'tooltip.diagShear.title': "전단력 (V)",
  'tooltip.diagShear.desc': "각 부재를 따른 전단력도. 값이 급변하는 곳은 집중하중이 있음을 나타냅니다.",
  'tooltip.diagAxial.title': "축력 (N)",
  'tooltip.diagAxial.desc': "축력도. 양(+) = 인장(부재가 늘어남), 음(−) = 압축.",
  'tooltip.diagAxialColor.title': "축력 색상 (N±)",
  'tooltip.diagAxialColor.desc': "축력에 따라 부재에 색을 입힙니다: 빨강 = 인장, 파랑 = 압축. 두께는 크기에 비례합니다.",
  'tooltip.diagColorMap.title': "컬러 맵",
  'tooltip.diagColorMap.desc': "선택한 부재력(모멘트, 전단력, 축력 또는 σ/fy 비)에 따라 색상 척도로 부재에 색을 입힙니다.",
  'tooltip.supFixed.title': "고정단",
  'tooltip.supFixed.desc': "수평 변위(ux), 수직 변위(uy), 회전(θ)을 구속합니다. 어떤 움직임도 허용하지 않습니다.",
  'tooltip.supPinned.title': "핀 지점",
  'tooltip.supPinned.desc': "ux와 uy를 구속하지만 회전은 허용합니다. 부재는 이 점에서 자유롭게 회전할 수 있습니다.",
  'tooltip.supRollerX.title': "롤러 X",
  'tooltip.supRollerX.desc': "uy(수직)만 구속합니다. 수평 이동과 회전을 허용합니다. 일반적인 \"롤러\" 지점입니다.",
  'tooltip.supRollerY.title': "롤러 Y",
  'tooltip.supRollerY.desc': "ux(수평)만 구속합니다. 수직 이동과 회전을 허용합니다.",
  'tooltip.supSpring.title': "스프링",
  'tooltip.supSpring.desc': "각 방향(kx, ky, kθ)의 강성을 설정할 수 있는 탄성 지점. 지반이나 유연한 연결을 모델링합니다.",
