  'seismic.blocked.zone0': "표 3.1은 지진 구역 0에 대한 스펙트럼을 정의하지 않습니다. 2.5.2조는 3층 또는 12 m 이하의 건물, 그리고 풍하중으로 검토하며 c1, c2, c3를 만족하는 더 높은 건물을 이 기준에서 면제합니다. 그룹 Ao는 면제되지 않습니다.",
  'seismic.blocked.siteSF': "지반 등급 SF는 현장별 평가가 필요합니다 (2.3.2조). 표 3.1에서 읽을 수 있는 행이 없습니다.",
  'seismic.assumed.faultProximity': "표 3.1에 인쇄된 근단층 최솟값을 채택했습니다: Na = {na}, Nv = {nv}. 기준에는 이 값을 높일 수 있는 단층 거리 표가 없습니다.",
  'seismic.f1.garageSpecial': "표 3.1은 차고를 (*)로 표시합니다. 이는 동시성 계수가 아니라 모든 공간이 점유된 상태와 실제 차량 중량을 반영한 하중 분석을 요구합니다.",
  'seismic.derivation.weight': "W = D + f1·L + f2·S = {dead} + {f1}·{live} + {f2}·{snow} = {total} kN (식 3.15).",
  'seismic.derivation.taOnly': "Ta = Cr·H^x = {cr}·{h}^{x} = {ta} s (식 6.8, 표 6.2).",
  'seismic.derivation.tComputed': "계산된 주기 T = {computed} s를 사용합니다. 이는 Cu·Ta = {cu}·{ta} = {limit} s 한계보다 작습니다 (식 6.7).",
  'seismic.derivation.tCapped': "계산된 주기 {computed} s가 식 6.7의 한계를 초과합니다: 대신 Cu·Ta = {cu}·{ta} = {limit} s를 사용합니다.",
  'seismic.derivation.cPlateau': "T = {t} s ≤ T2 = {t2} s이므로 C = 2.5·Ca·γr/R = {sa}·{gammaR}/{r} = {c} (식 6.3).",
  'seismic.derivation.cSpectrum': "T = {t} s > T2 = {t2} s이므로 C = Sa·γr/R = {sa}·{gammaR}/{r} = {c} (식 6.4).",
  'seismic.derivation.cFloorNearFault': "구역 3과 4에 대한 식 6.5의 하한이 지배합니다: C = 0.8·as·Nv/R = 0.8·{as}·{nv}/{r} = {c}.",
  'seismic.derivation.cFloorLowZone': "구역 0, 1, 2에 대한 식 6.6의 하한이 지배합니다: C = 0.11·Ca·γr = 0.11·{ca}·{gammaR} = {c}.",
  'seismic.derivation.dist': "Vo = {v0} kN을 Wk·hk / ΣWi·hi로 {levels}개 레벨에 분배합니다. ΣWi·hi = {sumWh} kN·m (식 6.11).",
  'seismic.derivation.distTopHeavy': "T = {t} s가 2·T2 = {t2} s를 초과합니다: Vo = {v0} kN의 90 %는 Wk·hk(ΣWi·hi = {sumWh} kN·m)로 {levels}개 레벨에 분배하고, 나머지 10 %는 최상단 질량에 전부 작용시킵니다 (식 6.12 및 6.13).",
  'seismic.derivation.distNoMass': "기준 레벨 위에 질량이 없습니다: 분배할 것이 없습니다.",
  'seismic.blocked.dynamicRequired': "2.7.3조는 동적 방법을 의무로 규정합니다: T = {t} s가 3·T2 = {limit} s를 초과합니다 (T2 = {t2} s). 높이와 관계없이 정적 방법은 적용되지 않습니다.",
  'seismic.blocked.heightOverTable25': "표 2.5는 구역 {zone}의 그룹 {group}에 대해 정적 방법을 {limit} m까지로 제한합니다. 이 건물의 높이는 {h} m입니다.",
  'seismic.blocked.irregular': "표 2.5는 평면과 입면이 모두 정형인 건물에 정적 방법을 허용합니다. 이 건물은 비정형으로 선언되었습니다.",
  'seismic.blocked.aoIrregular': "표 2.5는 그룹 Ao에 대해 표 2.3과 2.4의 1a행(비정형 없음)에서만 정적 방법을 허용합니다. 이 건물은 중간 정도의 비정형으로 선언되었습니다.",
  'seismic.assumed.groupCAsB': "표 2.5에는 그룹 C의 열이 없으므로 그룹 B의 행으로 읽습니다. 이는 그룹 C의 위험도 계수가 요구하는 것보다 더 엄격합니다.",
