  'dsm.mode2dBanner3dof': "2D 모드 — 절점당 3 자유도 (ux, uz, θy) · 행렬 6×6 (골조) / 4×4 (트러스)",
  'dsm.mode2dBanner2dof': "2D 모드 — 절점당 2 자유도 (ux, uy) · 행렬 4×4 (골조) / 4×4 (트러스)",
  'dsm.step1.explanation': "첫 단계는 구조물의 각 자유도(DOF)에 <strong>전체 번호</strong>를 부여하는 것입니다.",
