  'dsm.step1.restrained': "구속",
  'dsm.step2.explanation': "각 부재마다 자체 좌표계에서 <strong>국부 강성행렬</strong> [k]를 계산합니다.",
  'dsm.step2.whyTruss': "트러스 부재: 축력만 받습니다. 국부축에서는 축방향 자유도에 EA/L만 나타나고 횡방향 행은 0이며 회전은 없습니다. 부재는 절점에 회전 강성을 전혀 주지 않습니다.",
  'dsm.step2.whyHinge': "{end}단의 힌지: 이 단은 모멘트를 전달하지 않으므로 회전 θ{end}가 소거되어 해당 행과 열이 사라집니다. 부재는 일단 고정 타단 힌지 보가 됩니다. 12EI/L³는 3EI/L³가 되고, {other}단의 회전 강성은 4EI/L에서 3EI/L로 줄며, 전달률 2EI/L은 사라집니다.",
  'dsm.step2.whyBothHinged': "양단 힌지: 부재는 모멘트를 전혀 전달하지 않으며 휨 강성이 [k]에서 사라져 트러스 부재처럼 EA/L만 남습니다. 경간에 작용하는 하중은 단순보의 반력처럼 여전히 절점에 전달됩니다.",
  'dsm.step2.whyReleases3d': "여기서 해제됨: {list}. 각 해제는 해당 회전을 소거하여 행과 열이 사라지고, 그 휨 평면에서 12EI/L³는 3EI/L³가 됩니다(반대 단에서는 4EI/L이 3EI/L). 비틀림을 해제하면 GJ/L 블록 전체가 제거됩니다.",
  'dsm.step2.element': "부재:",
  'dsm.step2.type': "유형",
  'dsm.step2.frameNote3d': "축강성(EA/L), 두 평면의 휨(EIy, EIz), 비틀림(GJ/L)을 포함하는 12×12 행렬입니다.",
  'dsm.step2.trussNote3d': "6×6 행렬(3D 트러스): u₁, u₂ 대각 성분에 축강성 EA/L만 있습니다.",
  'dsm.step2.localMatrix': "[k] — 국부 행렬 ({rows}×{cols})",
