  'table.profile': "단면",
  'section.amorphousDefault': "무정형 단면",
  'section.customName': "사용자 정의 단면",
  'field.area': "면적 (A)",
  'field.jTorsion': "J (비틀림)",
  'field.resultName': "이름:",
  'stress.panelTitle': "단면 해석",
  'stress.close': "닫기 (Esc)",
  'stress.moveAlongElem': "부재를 따라 이동 (x/L)",
  'stress.forces3dHelp': "이 단면의 3D 부재력.\nN = 축력 (+ 인장, - 압축)\nVy = XY 평면의 전단력 (Mz 발생)\nVz = XZ 평면의 전단력 (My 발생)",
  'stress.moments3dHelp': "Mx = 비틀림모멘트\nMy = 국부 y축에 대한 모멘트 (높이 방향으로 휘며 Iy 사용)\nMz = 국부 z축에 대한 모멘트 (폭 방향으로 휘며 Iz 사용)\n회전하지 않은 기본 세장 단면: My는 강축(수직), Mz는 약축(수평)이며, 단면 회전 시 이 축들도 단면과 함께 회전합니다.\n규약: + = 정모멘트 (하부 섬유 인장)",
  'stress.rotDecompHelp': "단면 회전의 분해 ({angle}°).\nVy, Vz = 회전된 국부축에서의 전단력 성분",
  'stress.rotMomentHelp': "단면 회전에 따른 모멘트 M의 분해.\nMy = M·cos(α) (α=0에서 높이/강축 휨)\nMz = M·sin(α) (α=0에서 폭/약축 휨)\nα = {angle}°",
  'stress.forces2dHelp': "부재의 이 단면에서의 부재력.\nN = 축력 (+ 인장, - 압축)\nV = 횡방향 전단력\nM = 휨모멘트 (+ 정모멘트, 하부 인장)",
  'stress.criticalSections': "위험 단면",
  'stress.criticalSectionsHelp': "응력을 검토해야 하는 부재 상의 위치.\n\n최대 모멘트 지점(V=0), 지점, 집중하중 위치, 중간 지점을 포함합니다.\n각 칩을 클릭하면 해당 단면으로 이동합니다.",
  'stress.noGeomMsg1a': "단면 ",
  'stress.noGeomMsg1b': "의 정확한 외곽선은 아직 제공되지 않으므로 응력 분포, Mohr 원, 파괴 기준을 계산할 수 없습니다.",
  'stress.cpInKern': "핵 내부: σ 동일 부호",
  'stress.naOutside': "중립축 {arrow} 외부",
  'stress.rotSuffix': "(회전 {angle}°)",
  'stress.noGeomMsg2': "이는 단면의 성질이 아니라 자료 부족에 따른 제약입니다. 단면은 완전히 정의되어 있으며 전체 해석은 공표된 값을 정상적으로 사용합니다.",
  'stress.noGeomMsg3': "MC를 제외한 모든 카탈로그 계열이 상세 해석을 지원합니다. 그중 하나를 지정하거나 치수를 명시하여 단면을 구성하십시오.",
  'stress.amorphMsg1': "선택한 단면은 <strong>무정형</strong>입니다 (정의된 기하 형상 없음).",
  'stress.amorphMsg2': "무정형 단면은 응력 분포 해석, Mohr 원, 파괴 기준을 지원하지 않습니다.",
  'stress.amorphMsg3': "단면 해석을 사용하려면 표준 단면을 지정하거나 기하 형상이 있는 단면을 구성하십시오.",
  'stress.compositeMsg': "이 단면은 여러 재료를 결합한 것입니다. 단면 성질은 환산 단면의 값이며, 상세 응력장은 단일 재료에 대해서만 계산되므로 표시하지 않습니다. 결과의 부재 응력에는 각 재료가 반영됩니다.",
  'stress.stressState': "응력 상태",
  'stress.sigmaBiaxHelp': "2축 수직응력 (Navier):\nσ = N/A − My·y/Iy + Mz·z/Iz\n\n양수 = 인장 (빨강)\n음수 = 압축 (파랑)\n\n선택한 섬유 (y, z)에 따라 달라집니다.",
  'stress.tauTotalHelp': "횡방향 전단 단독 또는 비틀림 전단 단독의 크기.",
  'stress.combinedShearRefused': "비틀림 전단과 횡방향 전단이 겹칩니다. 조합 응력 결과는 제공하지 않습니다.",
  'stress.vonMisesHelp': "Von Mises 기준 (변형에너지):\nσvm = √(σ² + 3τ²)\n\n강재와 연성 금속에 적합합니다.\n백분율은 fy 사용률을 나타냅니다.",
  'stress.trescaHelp': "Tresca 기준 (최대 전단응력):\nτmax = √((σ/2)² + τ²)\n\nVon Mises 대비 약 15% 보수적입니다.\n동등식: 2τmax ≤ fy",
  'stress.rankineHelp': "Rankine 기준 (최대 수직응력):\nmax(|σ₁|, |σ₃|) ≤ fy\n\n취성 재료(콘크리트, 암석)에 적합합니다.\n강재에는 Von Mises를 권장합니다.",
  'stress.neutralAxis': "중립축:",
  'stress.neutralAxis3dHelp': "σ=0인 조합 중립축.\n2축 휨(Mz와 My)에서는 중립축이 비스듬할 수 있습니다.\nθ는 Z축(수평)으로부터의 각도입니다.",
  'stress.sigma2dHelp': "수직응력 (Navier 식):\nσ = N/A + M·y/I\n\n양수 = 인장 (빨강)\n음수 = 압축 (파랑)\n\n선택한 섬유 (y)에 따라 달라집니다.",
  'stress.tauMassiveHelp': "전단응력 (Jourawski):\nτ = V·Q(y) / (I·b)\n\nQ(y) = y 위쪽 면적의 1차 모멘트.\n중립축에서 최대, 자유 가장자리에서 0.\n직사각형 단면에서는 포물선 분포.\n\n가정: τ는 폭 b에 걸쳐 균일.\n폭이 넓은 단면(b ≈ h)에서는 근사값이며,\n실제 값은 z에 따라 변합니다 (중앙에서 최대).",
  'stress.tauThinHelp': "전단응력 (Jourawski):\nτ = V·Q(y) / (I·b)\n\nQ(y) = y 위쪽 면적의 1차 모멘트.\n중립축에서 최대, 자유 가장자리에서 0.\n\n박벽 단면에서는 τ가 두께에 걸쳐\n균일하다는 가정이 매우 정확합니다.",
  'stress.neutralAxisLabel': "(중립축)",
  'stress.note2dTauOnly': "2D 해석: 전단력 V에 의한 τxy만 고려",
  'stress.note2dNoTorsion': "비틀림(T=0)이나 면외 전단(Vz=0) 없음",
  'stress.neutralAxis2dHelp': "중립축 (σ = 0):\ny_NA = -N·Iz / (A·M)\n\n수직응력이 0이 되는 위치.\n양수 = 도심 위쪽.\nN=0이면 중립축은 도심(y=0)을 지납니다.",
  'stress.centralCore': "단면 핵",
  'stress.centralCoreHelp': "단면 핵은 단면의 기하 성질입니다.\nσ의 부호가 바뀌지 않으면서 N이 작용할 수 있는 영역을 정의합니다.\n단면의 단면 핵 버튼을 켜면 표시됩니다.",
  'stress.ccDesc1': "<strong>단면 핵</strong>은 단면의 기하 성질이며 작용 하중과 무관합니다.",
  'stress.ccDesc2': "수직응력 σ의 부호가 바뀌지 않으면서 축력 N이 작용할 수 있는 도심 주위의 영역을 정의합니다. 압력 중심이 단면 핵 안에 있으면 단면 전체가 순수 인장 또는 순수 압축 상태입니다.",
  'stress.ccLimitZ': "수평축 방향",
  'stress.ccLimitY': "수직축 방향",
  'stress.ccEquations': "식",
  'stress.ccEqDesc': "도심에서 거리 <em>d</em>에 있는 각 최외곽 섬유에 대해 단면 핵의 꼭짓점은 다음 위치에 있습니다:",
  'stress.ccEqWhere': "여기서 W = 단면계수, A = 면적, I = 단면2차모멘트, d = 최외곽 섬유까지의 거리.",
  'stress.sectionLabel': "단면:",
  'stress.ccShapeLabel': "단면 핵 형상:",
  'stress.shapeRect': "직사각형",
  'stress.shapeIH': "I/H 단면",
  'stress.shapeCHS': "중공 원형 (CHS)",
  'stress.shapeRHS': "중공 직사각형 (RHS)",
  'stress.shapeT': "T",
  'stress.shapeL': "L (앵글)",
  'stress.shapeC': "C (채널)",
  'stress.coreCircular': "원형",
  'stress.coreHexagonal': "육각형",
  'stress.coreDiamond': "마름모",
  'stress.ccRectNote': "반축 e<sub>y</sub> = h/6, e<sub>z</sub> = b/6인 마름모",
  'stress.ccIHNote': "육각형: 꼭짓점은 (0, ±I<sub>z</sub>/(A·h/2)) 및 (±I<sub>y</sub>/(A·b/2), ±I<sub>z</sub>/(A·y<sub>web</sub>))",
