  'stress.fiberYZ3dHelp': "응력을 평가하는 단면 Y, Z축 상의 위치.\nY (높이): My에 의한 휨이며 Iy 사용. Z (폭): Mz에 의한 휨이며 Iz 사용.\n회전하지 않은 기본 방향에서는 Y가 강축이며, 단면을 회전하면 이 방향도 함께 회전합니다.\n노란 점은 선택한 섬유를 나타냅니다.",
  'stress.fiberY2dHelp': "응력을 평가하는 단면 내 높이.\ny = 0은 중심 (N=0이면 중립축).\n슬라이더를 움직여 하부에서 상부 섬유까지 훑어봅니다.\n양 끝에서는 수직응력이 최대이고 전단응력이 최소입니다.",
