  'stress.shearCentreMsg': "단면이 비틀리지 않고 휘려면 횡하중이 이 점을 지나야 합니다. 도심 기준:",
  'stress.devTitle': "공칭 치수",
  'stress.devBody': "이 단면의 표는 공칭 치수를 게시하고 면적은 공칭 질량에서 도출하므로, 둘은 출처에서부터 일치하지 않습니다. 아래 해석은 그려진 외곽선과 일치하며, 게시된 값과는 다음만큼 차이가 납니다:",
  'cat.code': "기준",
