  'cat.note.aisc': "W, HP, M, C, MC는 미국 시리즈이며 ASTM A6/A6M에 따른 치수입니다. AISC 360은 중공 단면을 ASTM A500과 A1085를 통해 다룹니다.",
  'cat.note.nbr': "브라질 압연 단면은 ASTM A6/A6M과 치수가 동등한 NBR 15980을 따릅니다. 형상이 같으므로 여기서는 미국 시리즈도 사용할 수 있습니다.",
  'cat.note.eurocodeTubes': "여기의 강관 표는 IRAM-IAS 것이며, EN 10219-2는 모서리 반경을 범위로 둡니다.",
  'cat.note.cirsoc': "설계 검토 기준이며, 단면은 현지 실무에서 사용하는 치수 규격에서 가져옵니다.",
