  'kin.allHingedNoMoment': "절점 {node}의 모든 부재가 힌지이므로 모멘트가 전달되지 않습니다. 부재: {elems}.",
  'kin.allHingedSupportNoRot': "절점 {node}의 모든 부재가 힌지이고 지점({support})은 회전을 구속하지 않습니다.",
