  'kin.nodeFreeEnd': "절점 {node}은(는) 자유단입니다. 부재 {elem}에만 연결되어 있고 지점이 없습니다.",
  'kin.biArtVertical': "절점 {node}에 연결된 부재({elems})는 양단 힌지이며 수직이므로 수직 축력만 전달하고 {dir} 강성이 없습니다.",
  'kin.biArtHorizontal': "절점 {node}에 연결된 부재({elems})는 양단 힌지이며 수평이므로 수평 축력만 전달하고 {dir} 강성이 없습니다.",
  'kin.collinearHinged': "절점 {node}의 부재들은 일직선상에 있고 모두 힌지이므로 수직 방향으로 저항 없이 미끄러질 수 있습니다.",
  'kin.noSupportAllHinged': "절점 {node}에는 지점이 없고 모든 부재가 힌지이므로 어떤 부재에서도 {dir} 강성을 받지 못합니다.",
  'kin.insufficientDirConstraint': "절점 {node}의 {dir} 구속이 충분하지 않습니다. 지점과 연결된 부재의 힌지를 확인하십시오.",
  'kin.genericUnconstrained': "절점 {node}의 자유도 \"{dof}\"이(가) 구속되지 않았습니다. 지점과 힌지의 조합만으로는 그 방향을 안정시키기에 부족합니다.",
  'kin.sugAddFixed': "회전을 구속하도록 절점 {node}에 고정단을 추가하십시오.",
  'kin.sugAddHorizSupport': "절점 {node}에 수평 변위를 구속하는 지점(핀, 고정단 또는 수직 롤러)을 추가하십시오.",
  'kin.sugAddVertSupport': "절점 {node}에 수직 변위를 구속하는 지점(핀, 고정단 또는 수평 롤러)을 추가하십시오.",
  'kin.sugUpgradeSupport': "회전을 구속하도록 절점 {node}의 지점을 {type}에서 고정단으로 변경하십시오.",
  'kin.sugRemoveHinge': "모멘트가 전달되도록 절점 {node}의 부재 {elem}({end}단)에서 힌지를 제거하십시오.",
  'kin.sugGlobalHorizontal': "구조물에 전체 수평 구속이 없습니다. 수평 변위를 구속하는 지점(핀, 고정단 또는 수직 롤러)이 하나 이상 있는지 확인하십시오.",
  'kin.sugGeneric': "지점과 힌지의 조합을 확인하십시오. 구조물이 안정하려면 구속이 더 필요합니다.",
  'material.steelA36': "강재 A36",
