  'edu.author.helpCharWhat': "학생이 직접 구해서 입력해야 하는 값입니다. 앱이 구조물을 해석하여 학생의 답을 그 결과와 비교해 채점합니다.",
  'edu.author.helpCharEx': "학생에게는 다음과 같이 보입니다.\n  Mmax = [____] kN·m\n확인하면 해석기가 낸 값과 비교하여 정답 또는 오답으로 채점됩니다.",
