  'edu.author.helpDiagEx': "예를 들어 부재 1의 중간 지점에서 \"지간 중앙의 모멘트는 얼마입니까?\"라고 묻습니다. 학생은 숫자로 답합니다.",
  'edu.author.helpShapeWhat': "학생이 값을 계산하지 않고 각 부재력도의 형상을 고릅니다. 분포하중이 포물선 모멘트와 직선 전단력을 만든다는 것을 알아보는 훈련입니다.",
  'edu.author.helpShapeEx': "학생에게는 0, 일정, 직선, 포물선의 네 가지 선택지가 보이며 부재력도마다 하나를 고릅니다.",
  'edu.author.helpKinWhat': "학생이 구조물이 정정인지 부정정인지, 그리고 몇 차인지 판단합니다. 직접 정할 필요는 없습니다. 앱이 계산합니다.",
