  'stair.warnWaist': "경사 지간 {span} m에 슬래브 두께 {waist} m는 세장합니다. 처짐을 확인하세요.",
  'pro.shellCurvature': "곡률(쉘)",
  'pro.shellCurvatureHint': "곡선 사각형은 평면 MITC4가 아니라 퇴화 연속체로 해석되므로 곡률이 결과에 반영됩니다. 사각형에만 해당하며, 세 점은 정의상 한 평면 위에 있습니다.",
