  'pro.loadsHint': "\"하중 하나\"는 선택한 대상이나 지정한 대상에 하중을 입력합니다. \"기준으로 생성\"은 모델과 프로젝트의 기준으로부터 케이스, 하중, 조합을 만듭니다.",
  'pro.lcTableHint': "유형은 각 케이스가 기준의 조합에 어떻게 들어가는지를 결정합니다. §는 생성기에서 케이스의 매개변수를 열고, 눈 아이콘은 뷰에서 케이스를 표시하거나 숨기며, ⧉는 하중과 함께 복제하고, ⚙는 옵션을 엽니다.",
