  'selfWeight.migrated': "자중은 이제 하중 케이스 \"{case}\"의 하중으로 각 부재를 따라 작용합니다. 이전에는 절점에 집중되어 있었으므로 보의 모멘트가 달라집니다.",
  'selfWeight.migratedMany': "자중은 이제 하중 케이스 \"{case}\"의 하중입니다. 이전에는 고정하중 케이스 {n}개 모두에 들어가 {n}번 반영되었으므로, 다른 케이스에 넣어야 하는지 확인하십시오.",
  'analysisRules.combinations': "하중조합",
