  'analysisRules.pdeltaOneWay': "단방향 부재나 들림 지점이 있으면 조합은 활성 집합으로 해석하며 P-Delta는 적용하지 않습니다.",
  'loads.frame': "축",
  'loads.frameHelp': "국부: qx는 부재 방향(축방향), qy와 qz는 부재의 국부 축 방향. 전체: 전체 축 방향, 부재 길이 1 m당. 투영: 전체 축 방향, 부재 투영 길이 1 m당(예: 지붕 서까래의 적설을 평면 길이 1 m당으로 표시).",
  'loads.frame.local': "국부",
  'loads.frame.global': "전체",
  'loads.frame.projected': "투영",
  'results.pdeltaUnstable': "2차 평형이 성립하지 않아(하중에 도달하기 전에 구조물이 좌굴) 부재력이 없습니다: {names}.",
  'shellFaces.title': "표면, 기준 및 횡전단력 (kN/m², kN/m)",
  'shellFaces.type': "유형",
  'shellFaces.topVm': "σvM 상면",
  'shellFaces.bottomVm': "σvM 하면",
  'shellFaces.topTresca': "Tresca 상면",
