  'shellFaces.plate': "삼각형",
  'shellFaces.quad': "사각형",
  'shellFaces.note': "표면: 막 ± 6M/t², 상면은 국부 z를 따라 z = +t/2. qx와 qy는 MITC4 사각형 요소에만 있습니다. CSV와 Excel에는 국부 및 전체의 모든 열이 포함됩니다. 곡면 쉘의 휨모멘트와 표면 응력은 제공되지 않으며, 대시나 빈칸은 0이 아닙니다.",
  'wb.cover.project': "프로젝트",
