  'wb.cover.exported': "내보낸 시각",
  'wb.cover.build': "버전(커밋)",
  'wb.cover.units': "단위",
  'wb.cover.massRefs': "반영되지 않은 질량 중량",
  'wb.cover.massRefsValue': "질량 중량 {n}개가 영역 또는 그룹에 작용합니다. MassSource 시트에 나열되어 있으나 가져오기에서는 영역이나 그룹을 읽을 수 없으므로 보고만 하고 제외합니다",
  'wb.cover.stations': "부재를 따른 측점",
  'wb.cover.stationsEqual': "양 끝을 포함해 {n}개를 등간격으로 배치",
  'wb.cover.stationsCritical': "주요 위치: 4등분점, 하중 위치, 전단력 0인 위치",
  'wb.cover.cases': "하중 케이스",
  'wb.cover.combinations': "하중조합",
  'wb.cover.case': "케이스",
  'wb.conv.axes': "전체 축: X와 Y는 수평, Z는 위쪽, 오른손 좌표계. 변위와 반력은 전체 축 기준입니다.",
  'wb.conv.localAxes': "부재 국부 축: x는 절점 I에서 절점 J 방향, y와 z는 국부 Y 벡터와 롤 각을 따릅니다. 내보낸 롤 각에는 부재 롤과 단면 회전이 모두 포함되며 단위는 도입니다.",
  'wb.conv.sources': "결과 출처: 케이스와 조합은 해석된 하중 케이스 또는 조합을 나타냅니다. 단독(sourceId 0)은 개별 하중 케이스가 아닌 독립 해석입니다. 포락선 내보내기는 출처 envelope와 id 0을 사용하며 표시된 포락선 이름을 씁니다. Magnitude는 SRSS 또는 ABS 조합으로, 값은 부호 없는 크기이며 평형 상태가 아니고 최댓값과 포락선에서 제외됩니다.",
  'wb.conv.selfWeight': "SelfWeight는 방향, 계수, 적용 범위를 기록합니다. 별도의 기존 단일 행이 중력을 정의하지 않는 한 케이스 규칙은 전체 하중 해석에도 적용됩니다. 기존 케이스 행과 단일 행은 택일 관계이며 합산되지 않습니다. 케이스 규칙과 기존 독립 중력은 가져오며, 지원되지 않는 범위는 보고합니다.",
  'wb.conv.selfWeightImport': "SelfWeight는 방향, 계수, 적용 범위를 기록합니다. 별도의 기존 단일 행이 중력을 정의하지 않는 한 케이스 규칙은 전체 하중 해석에도 적용됩니다. 기존 케이스 행과 단일 행은 택일 관계이며 합산되지 않습니다. 케이스 규칙과 기존 독립 중력은 가져오며, 지원되지 않는 범위는 보고합니다.",
  'wb.conv.units': "전체 SI 단위: m, kN, kN·m. 부재 응력과 계수는 MPa, 쉘 응력은 kN/m², 쉘 모멘트는 kN·m/m로 화면 표시와 같습니다. 회전은 rad, 온도는 °C입니다. 각 머리글에 단위가 대괄호로 표시됩니다.",
  'wb.conv.displacements': "변위: 각 절점의 병진 ux, uy, uz와 X, Y, Z축 회전을 해석된 값 그대로 표시합니다.",
  'wb.conv.reactions': "반력: 지점이 구조물에 가하는 힘과 모멘트로 전체 축 기준이며, 작용 하중과 평형을 이룹니다.",
  'wb.conv.memberForces': "부재력은 국부 축 기준이며 해석기의 부호를 따릅니다. 이는 화면의 선도가 보여 주는 부호와 같습니다. N은 인장이 양(+)이고, Vy, Vz, T, My, Mz는 선도에 그려진 대로입니다.",
  'wb.conv.stations': "측점: 각 부재를 따른 지점이며 x는 절점 I에서 잰 거리입니다. 처음과 마지막은 부재 양 끝이며, 이곳의 측점 부재력은 단부력과 같습니다.",
  'wb.conv.deflections': "처짐: 변위된 부재 양 끝을 잇는 현에 대한 각 측점의 변위로, 국부 y(v)와 z(w) 방향 및 그 합성값입니다.",
  'wb.conv.stresses': "응력: 각 측점에서 단면의 최대 및 최소 수직응력이며 인장이 양(+)입니다. 기준 \"geometry\"는 단면 윤곽을, \"bounds\"는 단면의 외접 사각형을 읽습니다.",
  'wb.conv.shells': "쉘은 각 요소의 중심에서: 요소 국부 축(x는 첫 번째 변 방향, z는 그에 수직) 기준의 막응력 σxx, σyy, τxy와 모멘트 mx, my, mxy, 그리고 MITC4 사각형 요소의 횡전단력 qx, qy. 전체 열은 같은 응력, 모멘트, 전단력을 전체 축으로 변환한 것이며, 곡면 사각형 요소에는 없습니다.",
  'wb.conv.shellFaces': "쉘 표면: 막에 상면(국부 z를 따라 z = +t/2)과 하면(−)의 6M/t²를 더한 값으로, 각각 주응력 σ1, σ2, 국부 x에서 σ1까지의 각도, Von Mises와 Tresca(σ3 = 0)를 포함합니다. 막 단독 값도 있습니다. 곡면 쉘은 휨모멘트나 표면 응력이 복원되지 않으므로 해당 셀은 비어 있고 최댓값에서 제외됩니다. 두께가 없거나 올바르지 않을 때도 표면 셀은 비어 있습니다.",
  'wb.conv.shellNodes': "쉘 절점: 각 절점 주변 요소의 평균값을 전체 성분으로 나타낸 것입니다. 쉘 모서리: 해석 엔진이 보고하는 각 요소 모서리의 자체 Von Mises 값으로, 삼각형은 더 불리한 면, 사각형은 막 기준입니다.",
  'wb.conv.envelope': "포락선: 각 절점, 부재 단부, 성분에 대해 조합 전체(조합이 없으면 케이스 전체)에서의 최댓값과 최솟값을 그 값을 만드는 조합과 함께 표시합니다.",
  'wb.conv.maxima': "최댓값: 각 성분에 대해 어디서든 나타나는 최댓값과 최솟값, 발생 위치 및 해당 조합. 부재력은 측점에서 읽습니다.",
  'wb.conv.statics': "정역학: 케이스와 조합별로 작용 합력, 반력의 합력, 전체 원점에 대한 그 합을 나타내며, worstRelative는 하중 대비 가장 큰 잔차입니다.",
  'wb.conv.secondOrder': "2차 해석: P-Delta로 해석한 조합. 2차 평형이 성립하지 않는 조합(하중에 못 미쳐 구조물이 좌굴)은 결과 행이 없으며 여기에 나열됩니다.",
  'wb.conv.oneWay': "단방향 부재와 들림 지점: 각 결과의 활성 집합 해석으로, 느슨해진 부재와 들린 지점을 표시합니다.",
  'wb.conv.model': "모델 시트는 가져오기 기능의 시트 이름과 열 키를 사용하므로 다시 읽을 수 있습니다. 가져오기에서 인식하지 못하는 열은 건너뜁니다. 단면 성질은 해석 엔진에 전달된 값입니다.",
  'wb.conv.text': "수식으로 오인될 수 있는 +, -, =, @로 시작하는 텍스트 셀은 없습니다. 앞의 마이너스는 마이너스 기호(−)로 기록합니다.",
  'wb.conv.precision': "숫자는 전체 정밀도로 기록됩니다. xlsx 파일이 담을 수 있는 크기를 넘거나 400만 셀을 초과하는 통합 문서는 시트당 CSV 하나씩을 담은 zip으로 기록됩니다.",
  'wb.zipped': "통합 문서가 xlsx 파일로 처리하기에는 너무 커서 시트당 CSV 하나씩을 담은 zip으로 기록했습니다.",
