  'pro.shellInfoMesh': "메쉬 분할은 슬래브/벽을 더 작은 사각형으로 나누어 모든 변을 따라 쉘 절점을 더 많이 만듭니다.",
  'pro.shellInfoSplit': "이렇게 새로 생긴 변 위 절점을 보와 공유하지 않으면 하중이 그 보를 따라 연속적으로 전달되지 않고 원래 모서리에서만 전달됩니다. \"주변 보 분할\"을 켠 상태(기본값)로 두십시오. 생성기가 각 변의 보를 메쉬 절점에서 분할하여 절점을 공유하게 합니다. 직접 절점을 공유하거나 분할하는 경우에만 끄십시오.",
  'pro.shellInfoSlab': "수동 방법: 먼저 지지 보를 분할한 다음, 슬래브 변의 절점이 보 절점과 일치하도록(절점 ID 공유) 슬래브를 메쉬로 나눕니다. 절점이 일치하면 연결되고, 일치하지 않는 변 사이에는 하중이 전달되지 않습니다.",
