  'design.reason.provisionalBiaxial': "부재 {elementId}: 잠정 제안. {designed}축은 일반 탐색으로 설계 및 검증되었습니다. {unchecked}축({secondary} kN·m, 주 모멘트 {primary} kN·m의 {percent}%)과 그 전단력 {uncheckedShear}는 이 앱의 어떤 검토로도 평가되지 않습니다. 표시된 철근은 주축 설계이며, 검토하지 않은 축에 대해서는 어떤 강도도 가정하지 않았고 어떤 기준값도 완화하지 않았습니다. 그 축을 직접 설계하지 않으면 시공도서로 유효하지 않습니다.",
