  'loadPlan.blocked.seismicMass.snow': "{elevation} m에서 지진하중이 거부되었습니다. 참여하는 적설 질량을 지지하는 실제 부재를 확정할 수 없었습니다.",
  'loadPlan.blocked.seismicMass.torsion': "{elevation} m에서 지진하중이 거부되었습니다. 우발 비틀림을 부재 압력장으로 표현할 수 없었습니다.",
  'loadPlan.blocked.modalUnavailable': "모드 부재력 분포가 수정될 때까지 모드 지진하중 생성을 사용할 수 없습니다. 정적 방법을 사용하세요.",
  'loadPlan.blocked.seismicDiagonalTorsion': "45° 지진 케이스는 우발 비틀림과 함께 사용할 수 없습니다.",
  'loadPlan.blocked.seismicBase': "정적 지진하중 생성에는 유효한 표고에서 지진 질량과 연결된 지점이 필요합니다.",
  'loadPlan.blocked.seismicSteppedBase': "단차가 있는 기초에는 정적 지진하중을 생성할 수 없습니다. 지진 질량과 연결된 지점은 같은 표고에 있어야 합니다.",
  'loadPlan.blocked.seismicBelowDatum': "참여하는 지진 질량이 지점 기준면 아래에 있으면 정적 지진하중을 생성할 수 없습니다.",
  'loadPlan.blocked.seismicDisconnected': "정적 지진하중을 생성하려면 지진 질량이나 평면 폭에 기여하는 모든 요소가 지점이 있는 하나의 연결된 구조에 속해야 합니다.",
  'loadPlan.blocked.seismicMass.weight': "{elevation} m에서 지진하중이 거부되었습니다. 실제 질량 또는 층 힘이 유효하지 않습니다.",
  'loadPlan.blocked.seismicMass.storyNode': "{elevation} m에서 지진하중이 거부되었습니다. 질량을 지지하는 부재에 이 층 레벨의 연결 절점이 없습니다.",
  'loadPlan.blocked.seismicAmbiguousStory': "가새 접합부 또는 지붕 접합부에 층을 정할 바닥 골조나 격막이 없으므로 정적 지진하중을 생성할 수 없습니다.",
  'loadPlan.blocked.seismicStoryPrecision': "좌표 정밀도가 너무 낮아 접합부가 직선 부재를 분할하는지 판단할 수 없습니다. 모델을 원점에 더 가깝게 옮기고 접합부 좌표를 확인하세요.",
  'loadPlan.blocked.seismicMass.slopedMember': "{elevation} m에서 지진하중이 거부되었습니다. 경사 부재에 참여 질량이 있는데 그 양단 표고에 바닥 골조나 격막의 근거가 없습니다.",
  'loadPlan.blocked.seismicNoR': "Table 5.1은 \"{system}\"에 대한 반응수정계수 R을 제시하지 않습니다. 1행은 값이 아니라 벽체 배치에 대한 식을 표시하며, 그 밖의 비어 있는 행은 식별되지 않은 시스템입니다. 스펙트럼을 나눌 값이 없습니다.",
  'loadPlan.blocked.roleUnusable': "\"{role}\" 역할({name})을 사용할 수 없습니다. 기준을 선택하고 설정을 완료하세요.",
  'loadPlan.blocked.windRoleUnusable': "풍하중이 요청되었지만 사용할 수 있는 풍하중 기준이 지정되지 않았습니다.",
  'loadPlan.blocked.seismicRoleUnusable': "지진하중이 요청되었지만 사용할 수 있는 내진 기준이 지정되지 않았습니다.",
  'loadPlan.blocked.roofDeadWithoutFloors': "지붕은 바닥의 고정하중을 받는데 이 모델에는 바닥이 없습니다. 지붕 섹션에 지붕 자체의 고정하중(지붕판, 퍼린, 단열재)을 입력하세요.",
  'loadPlan.blocked.unknownOccupancy': "알 수 없는 용도 \"{key}\".",
  'loadPlan.blocked.occupancyCrossReference': "이 용도는 값을 제시하지 않고 조항 {article}을 참조합니다. 하중을 직접 입력하세요.",
