  'loadPlan.disposition.retained': "케이스 {caseType}이(가) 있지만 계획은 이를 생성하지 않습니다. 그 하중은 유지됩니다.",
  'loadPlan.disposition.cleared': "케이스 {caseType}이(가) 있지만 계획은 이를 생성하지 않으며, 기존 하중을 대체하면 삭제됩니다.",
  'loadPlan.warning.caseCleared': "하중 케이스 {caseType}과(와) 그 모든 하중이 삭제됩니다. 계획이 이를 생성하지 않고 \"생성된 하중 대체\"가 켜져 있기 때문입니다.",
  'loadPlan.warning.caseRetainedNotCombined': "하중 케이스 {caseType}은(는) 유지되지만 계획이 이를 생성하지 않으므로 다시 생성한 조합에는 포함되지 않습니다. 해당 작용을 활성화하거나 직접 조합하세요.",
  'loadPlan.warning.addedOnTopOfExisting': "계획이 기존 케이스 {count}개({cases})를 대체하지 않고 거기에 추가하므로 그 하중이 두 번 계산됩니다. 생성기가 작성한 것을 다시 생성하려면 \"생성된 하중 대체\"를 체크하세요. 직접 입력한 것은 유지됩니다.",
  'loadPlan.warning.unmarkedKept': "대체하더라도 다시 생성되는 케이스({cases})의 하중 {loads}개와 이를 사용하는 조합 {combinations}개는 생성기가 표시하지 않았으므로 유지되며, 그 위에 계획이 추가됩니다. 이전 버전이 생성한 것이라면 모델에 각 하중과 조합이 두 번씩 들어갑니다. 아래의 \"함께 삭제\"를 체크하세요.",
  'loadPlan.warning.defaultsRemoved': "새 프로젝트가 시작할 때 갖는 예시 케이스({cases})와 조합 {combinations}개가 삭제됩니다. 하중이 없고 변경한 적이 없으며 계획의 조합이 이를 대체합니다.",
  'loadPlan.warning.unmarkedRemoved': "대체하면 다시 생성되는 케이스({cases})의 하중 {loads}개와 이를 사용하는 조합 {combinations}개도 삭제됩니다. 생성기가 표시하지 않은 것이며 직접 입력한 것도 포함됩니다.",
  'loadPlan.warning.definedKept': "계획이 작성하는 케이스({cases})에 있는 하중 {loads}개는 바닥 하중 정의에서 온 것입니다. 대체 여부와 관계없이 정의로 유지되며 계획이 그 위에 추가하므로, 바닥에 둘 다 있는 하중은 두 번 재하됩니다. 해당 정의를 삭제하거나(하중 › 바닥) 그 하중을 계획에서 제외하세요.",
