  'detailing.scene.status.HELD': "보류: 국부 검토 양호",
  'check.slabColumnJoint': "슬래브-기둥 접합부 이상화",
  'slabColumnJoint.point': "{level} m 층에서 슬래브는 각 기둥에 한 절점으로 접합됩니다. 이 메쉬에서는 슬래브 하중의 {share} %가 보를 거치지 않고 기둥으로 직접 전달되며, 이 비율은 메쉬에 의해 정해져 메쉬를 세분하면 0에 가까워집니다. 유한한 단면의 기둥은 보와 슬래브의 강성으로 정해지는 비율을 직접 받습니다. 슬래브 하중이 보와 기둥에 나뉘는 분배는 확립되지 않았으며, 이 부재의 설계 부재력은 구조물의 부재력으로 제시되지 않습니다. 이를 확립하려면 각 기둥 단면 안의 슬래브 절점을 기둥에 강체로 연결하고(기둥 면에 절점이 있는 메쉬에서) 다시 해석하십시오.",
  'slabColumnJoint.desk': "부재 {n}개에서 슬래브가 기둥에 한 절점으로 접합되어 있습니다. 하중이 보와 기둥에 나뉘는 분배는 메쉬에 따라 달라지며 확립되지 않았으므로, 이 부재들은 검증된 것으로 제시되지 않습니다.",
  'notice.D124.cause': "해당 층의 슬래브가 기둥에 한 절점으로 접합되어 있습니다. 기둥으로 직접 전달되는 하중 비율은 메쉬에 따라 달라지며, 부재가 설계된 기준이 된 보와 기둥 사이의 분배는 확립되지 않았습니다.",
  'notice.D124.fix': "각 기둥 단면 안의 슬래브 절점을 기둥에 강체로 연결하고(기둥 면에 절점이 있는 메쉬에서) 다시 해석하십시오.",
  'memo.code.slab-column-joint': "모델 (슬래브-기둥 접합부)",
  'detailing.document.slabColumnPointJoint': "검토용 초안 개정 {revision}: 슬래브가 기둥에 한 절점으로 접합된 부재 {pointJoints}개. 하중이 보와 기둥에 나뉘는 분배가 확립되지 않았습니다. 시공용 아님",
