  'detailing.convergence.incomplete': "{families}의 기술 배근 상세: 부재 {applicable}개 중 {detailed}개. 시공 문서가 아닙니다.",
  'detailing.convergence.emptyScope': "선택된 군이 없습니다. 문서화하려면 먼저 설계할 군을 선택하십시오.",
  'detailing.convergence.outOfScope': "범위 밖이며 모델에 있음: {families}.",
  'detailing.doc.vsDetailing': "배근 상세는 철근 골조를 조율합니다. 철근을 그리고, 충돌을 해결하며, 시공 가능 여부를 결정합니다. 이 단계는 그 골조에 대한 문서(도면, 철근 가공표, 보고서)를 발행하고 전문가 검토를 기록합니다. 철근의 편집은 배근 상세의 일이며, 무엇을 사무소 밖으로 내보낼지 결정하는 일은 여기의 일입니다.",
  'detailing.doc.select.title': "문서화 대상",
