  'codes.cirsoc201.anchorage.developmentMinimum': "Ø{db}에 대해 ld를 {computed} mm로 계산했으며 ({row}, 표 25.4.2.3), §25.4.2.1(b)의 최솟값 {minimum} mm로 상향했습니다.",
