  'codes.cirsoc201.anchorage.lap': "{spliceClass}급 겹침이음 = {factor} × ld({ld} mm) = {lap} mm, {minimum} mm 이상 (표 25.5.2.1).",
  'detailing.joint.assumedJd': "내부 탄성 팔길이를 jd = {ratio} d로 취했습니다. §15.4.1.1은 휨으로 생기는 인장력과 압축력을 요구하지만 jd를 구하는 방법은 규정하지 않습니다. 이 값은 직사각형 단면에서 흔히 쓰는 값이며 기준에 규정된 값이 아닙니다.",
  'detailing.joint.unsupported.noIncidentBeams': "이 접합부에 접합되는 보가 없어 자유물체를 구성할 수 없습니다.",
  'detailing.joint.unsupported.biaxial': "평면 두 방향 모두에 보가 있는 접합부입니다. 2축 검토에서는 각 방향의 전단력을 각자의 Aj로 구성하고 그 효과를 조합해야 하지만 구현되어 있지 않습니다. 접합부 전단 미검증.",
  'detailing.joint.unsupported.equilibriumResidual': "접합부 자유물체가 닫히지 않습니다. 기여하는 가장 큰 힘의 {residual} %에 해당하는 평형 잔차가 한계 {limit} %를 넘습니다. 접합부 전단 미검증: 닫히지 않는 자유물체에서 얻은 결과는 검증이 아닙니다.",
