  'footing.ui.matConflictRow': "{a} / {b} — {cls}: 실측 {measured} mm, 소요 {required} mm.",
  'footing.ui.matNoConflicts': "간섭 검토에서 철근망과 관련된 간섭이 발견되지 않았습니다. 직교하는 X/Y 교차 {crossings}곳은 설계상의 접촉입니다. §25.2.1과 §25.2.2는 한 단 안에서와 평행한 단 사이의 평행한 철근 사이 순간격을 규정하며, 직교 격자는 어느 경우에도 해당하지 않습니다.",
  'footing.ui.matPunchingMoment.NEGLIGIBLE': "접합부의 불균형 모멘트 Msc = {msc} kN·m (성분 {x}와 {y})가 유의성 한계 {threshold} kN·m 미만입니다. 직접 전단이 지배합니다. 이것은 §8.4.4.2 검증이 아닙니다.",
  'footing.ui.matPunchingMoment.UNSUPPORTED_MOMENT_TRANSFER_NOT_EVALUATED': "펀칭 미검증. 접합부가 한계 {threshold} kN·m를 넘는 불균형 모멘트 Msc = {msc} kN·m (성분 {x}와 {y})를 전달하며, §8.4.4.2의 편심 전단 모멘트 전달은 구현되어 있지 않습니다. 하부 철근망은 검증되었으나 기초 전체는 검증되지 않았습니다.",
  'footing.ui.matPunchingMoment.UNSUPPORTED_MOMENT_NOT_FORMED': "펀칭 미검증. 접합부의 불균형 모멘트를 구성할 수 없었으므로 0이라고 주장하지 않습니다. 직접 전단만 검토하면 아무도 모멘트를 평가하지 않은 접합부가 통과하게 됩니다.",
  'footing.ui.matGeometrySteps': "물리 형상 계산 메모",
  'footing.ui.matAnchorageSteps': "정착 계산 메모",
  'footing.record.flexureGeometryNotReconciled': "하부 철근망은 DESIGNED 상태이지만 물리 형상이 상세표와 일치하지 않습니다: 차단 결과 {findings}건. 승인된 상세표와 어긋난 철근망을 그리면 아무도 설계하지 않은 철근이 모델, 도면, 내보내기에 반영되므로 철근을 생성하지 않습니다. 휨은 검증되지 않았습니다.",
  'footing.record.anchorageNotEvaluated': "측정할 물리 철근망이 없어 하부 철근의 정착은 평가되지 않았습니다. 이것은 정착 실패가 아니라 측정의 기준이 되는 형상이 없다는 뜻입니다.",
  'footing.record.topReinforcementNotEvaluated': "기초 {footing}: 상부 철근은 평가되지 않았습니다. 이 프로젝트에는 상부 철근이 불필요함을 보이는 확정된 계산이 없으므로, 불필요하다고 주장하지도 상부 철근을 설계하지도 않습니다. 하부 철근망 검증은 유효하지만, 이 항목이 열려 있는 동안 기초는 발행에 적합하지 않습니다.",
  'footing.geometry.noLayerOrder': "물리적 단 순서가 정해지지 않았으므로 ({rationale}) 철근을 그릴 높이가 없습니다. 보수적 포락 깊이에 그리면 아무도 선택하지 않은 높이의 철근이 모델에 들어가게 됩니다.",
  'footing.geometry.directionNotDesigned': "{axis} 방향이 설계되지 않았으므로 ({status}) 어느 방향의 형상도 생성하지 않습니다. §13.3.3은 양방향 철근을 요구하며 절반의 철근망은 철근망이 아닙니다.",
  'footing.geometry.elevationMismatch': "{axis} 방향: 철근 축 높이는 유효깊이 {implied} m를 의미하는데 설계는 {designed} m로 수행되었습니다. 철근이 설계된 깊이와 다른 깊이에 그려지게 됩니다.",
  'footing.geometry.countMismatch': "{axis} 방향, 구역 {region}: 상세표는 철근 {scheduled}개를 요구하나 배치 결과는 {placed}개입니다. 도면을 맞추려고 철근을 재배분하지 않습니다.",
  'footing.geometry.spacingMismatch': "{axis} 방향, 구역 {region}: 배치 간격은 {placed} mm이고 상세표의 간격은 {scheduled} mm입니다.",
  'footing.geometry.sideCoverShort': "{axis} 방향, 구역 {region}, 철근 {bar}: 철근 표면까지 측정한 측면 피복이 {measured} mm로 소요값 {required} mm보다 작습니다.",
  'footing.geometry.bottomCoverShort': "{axis} 방향, 철근 {bar}: 표면까지 측정한 하부 피복이 {measured} mm로 소요값 {required} mm에 못 미치며, 상부면까지는 {toTop} mm가 남습니다.",
  'footing.geometry.outsideConcrete': "{axis} 방향, 철근 {bar}: 철근이 콘크리트를 {over} mm 벗어납니다.",
  'footing.geometry.duplicateBar': "{axis} 방향: 철근 {a}와 {b}이(가) 같은 위치를 차지합니다.",
  'footing.geometry.clearSpacingShort': "{axis} 방향: 철근 {a}와 {b} 사이의 순간격이 {measured} mm로 §25.2.1의 {required} mm보다 작습니다. 이는 인접한 §13.3.3.3 구역 사이의 간격이며 어느 한 구역도 이를 배치하지 않습니다.",
  'footing.geometry.providedAsMismatch': "{axis} 방향: 생성된 철근의 단면적은 {placed} cm²이고 상세표에는 {scheduled} cm²로 되어 있습니다.",
  'footing.anchorage.insufficient': "{axis} 방향, Ø{diameter}: 직선 정착 {required} mm가 필요하나 기둥면에서 철근 끝까지 {side}측으로 확보된 길이는 {available} mm이며 {short} mm 부족합니다. 갈고리를 임의로 만들지 않으며 ld를 줄이지 않습니다.",
  'footing.anchorage.noGeometry': "물리 철근망이 없어 ({status}) 위험단면에서 확보되는 길이를 측정할 수 없습니다.",
  'footing.record.flexureDesignedNotModeled': "하부 철근망은 양방향 모두 DESIGNED 상태이며(요구값, 소요 철근량, 철근 개수, 기준에 맞는 간격) 모델링되지 않았습니다. 모델, 상세표, CAD 인계에 물리 철근이 없습니다. 요구값을 검증할 철근이 여전히 없으므로 휨은 검증되지 않은 상태로 남습니다.",
  'footing.record.flexureDesignFailed': "하부 철근망 설계가 실패했습니다. 선택된 직경으로는 이 기초에 허용되는 배근 배치를 찾지 못했습니다. 명시된 조건이 충족하지 못한 요구 사항을 알려 줍니다. 선택된 직경을 조용히 바꾸지 않았으며 적합하다고 보고되는 배치도 없습니다.",
