  'codes.placement.allowanceAssumed': "횡방향 배치 허용치 {allowance} mm는 CIRSOC 값이 아니라 프로젝트의 가정입니다. 표 26.6.2.1(a)는 유효깊이와 피복의 허용오차만 규정하며 평행한 철근 사이의 간격에 대해서는 아무것도 정하지 않습니다. 프로젝트 상세 속성에서 설정하십시오.",
