  'footing.migration.matDiameterUnsupported': "{axis} 방향에 저장된 하부 철근망 직경은 Ø{value}였으며 프로젝트 철근 카탈로그에 없습니다. 그대로 받아들이지 않고 Ø{fallback}(으)로 읽었습니다. 아무도 구할 수 없는 철근망은 설계가 아닙니다.",
  'footing.migration.matPolicyUnknown': "저장된 하부 철근망 간격 정책 “{value}”은(는) 이 버전이 모르는 값입니다. 간격은 기준에서 도출했으며, 이것이 구현된 유일한 정책입니다.",
  'footing.migration.layerOrderToAuto': "프로젝트에 어느 하부 철근망이 아래 단에 가는지 지정되어 있지 않아 단 순서를 자동으로 읽었습니다. 이는 이전 버전과 설계가 달라집니다. 이전에는 두 방향 모두 더 얕은 유효깊이(보수적 포락)로 설계했지만 이제는 각각 실제 깊이로 설계합니다. 순서는 기초 화면에서 직접 고정할 수 있습니다.",
