  'footing.cadv2.assembly.description': "조정된 기초 철근 조립체: 양방향 하부 철근망, 기둥 다우얼 철근, 시작 띠철근과 보조 띠철근, 기초 입체, 기둥 스텁, 그리고 그 사이의 접합면. 평가되지 않은 상부 철근은 포함하지 않습니다.",
  'footing.cadv2.family.starterCrosstie': "시작 보조 띠철근: 단면을 가로질러 철근 두 개를 걸치는 단일 다리 띠철근이며, 주철근이 이미 구속된 철근의 150 mm 범위 밖에 있을 때 §10.7.6.3에서 요구합니다.",
