  'proRibbon.cmdOtherCodesDesc': "활성 조합에서 AISC 360, EN 1993-1-1, AISI S100, ACI 318 또는 EN 1992-1-1에 따라 부재를 검토합니다.",
  'otherCodes.pick': "기준",
  'otherCodes.family.steel': "압연 강재와 강관",
  'otherCodes.family.coldFormed': "냉간성형 강재",
  'otherCodes.family.concrete': "철근콘크리트",
  'otherCodes.code.aisc360': "AISC 360 (LRFD)",
