  'otherCodes.code.aisiS100': "AISI S100 (LRFD)",
  'otherCodes.code.aci318': "ACI 318",
  'otherCodes.code.ec2': "EN 1992-1-1",
  'otherCodes.coverage.aisc360': "2축 대칭 I형과 H형 단면 및 강관: 인장, 압축(E3, 세장 요소는 E7 감소 적용), 횡비틀림 좌굴을 고려한 휨(F2, Cb = 1, 하중은 상부 플랜지에 작용), 전단(G2), 상관식(H1). 휨에서 비조밀 또는 세장한 단면과 Cv1 < 1인 전단은 평가하지 않음으로 표시합니다. 각 부재는 자체에 지정된 길이와 K를 사용합니다.",
  'otherCodes.coverage.ec3': "I형과 H형 단면(압연 카탈로그에서 고르면 압연, 아니면 용접)과 냉간성형 강관: 휨좌굴(표 6.2 곡선), 횡비틀림 좌굴(6.3.2, C1 = 1, 하중은 상부 플랜지에 작용), 휨, 전단, 축력. 등급은 필릿 반경을 제외하고 구하며, 4등급 I형과 RHS는 EN 1993-1-5 유효단면을 사용하고 4등급 CHS는 제외합니다. 6.3.3 상관식은 Annex B 계수와 Cm = 1을 사용합니다. 휨과 함께 작용하는 전단 및 복부 전단좌굴은 평가하지 않음으로 표시합니다.",
  'otherCodes.coverage.aisiS100': "단판 립 C형 단면: 유효폭(Appendix 1), 압축, 인장, 횡비틀림 좌굴을 고려한 휨(F2.1), 항복 범위의 복부 전단, 상관식. 뒤틀림 좌굴은 평가하지 않으므로 적합으로 표시되는 행이 없으며, 압축의 휨비틀림 좌굴과 약축 휨도 평가하지 않습니다. Z형 단면은 제외합니다.",
  'otherCodes.coverage.aci318': "각 부재에 지정된 배근이 있는 직사각형 단면: 축력을 받는 휨(P–M 선도)과 스터럽이 있는 전단. 보는 영역(지점부와 경간 중앙)별로, 기둥은 양면 철근으로 검토합니다. 철근은 420 MPa, 피복은 2.5 cm이며 CIRSOC 설계와 같습니다. 두 축에 대해 휨을 받는 부재는 제외합니다.",
  'otherCodes.coverage.ec2': "지정된 배근이 있는 직사각형 보: γc = 1.5, γs = 1.15, αcc = 1로 휨(6.1)과 전단(6.2)을 검토합니다. 휨은 축력을 고려하지 않으므로 기둥은 제외하며, 축력이 0.1·fcd·Ac를 넘는 보는 평가하지 않음으로 표시합니다. 철근은 420 MPa, 피복은 2.5 cm이며 CIRSOC 설계와 같습니다.",
  'otherCodes.run': "검토",
  'otherCodes.blocked.noCombos': "검토하려면 조합을 해석하십시오.",
