  'direct.source.direct': "직접 해석 (AISC 360, C장)",
  'direct.note': "조합별 2차 해석을 감소 강성(전체에 0.8·E, 강재 부재의 휨에는 τb)으로 수행하며, 하중이 작용하는 절점에 가상하중 Ni = 0.002·Yi를 적용합니다. 중력하중만의 조합은 +X, −X, +Y, −Y를 시도해 가장 큰 횡변위를 취하고, 횡하중이 있는 조합에서는 Δ₂/Δ₁이 1.7을 넘으면 가상하중을 더합니다. P-δ는 부재를 분할하지 않고 각 부재의 기하강성에서 구합니다. 이 변위는 사용성 검토용이 아닙니다.",
