  'autoLoad.patterns': "구조물 일부에 작용하는 하중 (§4.3.3)",
  'autoLoad.patternsHint': "체커보드(패널과 경간을 번갈아, 층마다 뒤집어서) 배치는 더 큰 정모멘트를 주고, 격자선 양쪽의 경간과 그 너머로 한 칸씩 건너뛴 경간에 재하하면 부모멘트가 생깁니다. 각 배치는 해당 하중이 주하중인 조합에서 전체 재하를 대체하는 케이스입니다. 저감된 Lr에도 같은 방식이 적용됩니다 (표 4.1, 주 n).",
  'autoLoad.roof.title': "지붕",
