  'regulations.name.cirsoc104': "CIRSOC 104 ({edition})",
  'loadPlan.blocked.snowRoleUnusable': "적설하중이 켜져 있지만 프로젝트에 적설하중 기준이 설정되어 있지 않습니다.",
  'snow.refused.exposureNA': "표 2에는 해당 지표 조도 구분과 지붕 노출 조합의 Ce가 없습니다 (N/A).",
  'snow.derivation.pf': "적설: pg = {pg} kN/m² ({source}), Ce = {ce}, Ct = {ct}, I = {i}, pf = 0.7·Ce·Ct·I·pg = {pf} kN/m² (식 1).",
  'snow.derivation.minimum': "완경사 지붕: pf는 {min} kN/m² 이상이어야 합니다 (§3.4). pf = {pf} kN/m²를 사용합니다.",
  'snow.derivation.ps': "경사 {slope}°, W = {w} m: Cs = {cs} (그림 2), 수평 투영면에 ps = {ps} kN/m².",
  'snow.derivation.psSurface': "{slope}° 경사의 지붕면에는 고유한 Cs = {cs}를 적용합니다. 그 면에 ps = {ps} kN/m².",
  'snow.derivation.rain': "적설 위의 비: {add} kN/m²를 더했습니다 (10장).",
  'snow.derivation.unbalanced': "불균형 하중 (§6.1): 풍하 쪽 {leeward} kN/m², 풍상 쪽 {windward} kN/m², 풍향마다 한 케이스.",
  'snow.note.noRoof': "적설을 적용할 지붕 부재를 찾지 못했습니다.",
  'snow.refused.roofPlane': "적설하중 생성에는 지붕 평면이 필요합니다. 일직선이 아닌 점으로 지붕 형상을 추가하십시오. 고립된 서까래로는 이 평면 범위의 면을 결정할 수 없습니다.",
  'snow.refused.stepDriftTransfer': "적설하중 생성은 지붕 단차의 드리프트를 지지 부재에 신뢰성 있게 전달할 수 없습니다. 적설하중을 직접 정의하십시오.",
  'snow.refused.slidingOverlap': "적설하중 생성은 부분적으로 겹치거나 떨어져 있는 처마에서의 미끄러짐을 해석할 수 없습니다. 완전히 정렬된 연속 상하 가장자리를 사용하십시오. 적설하중이 생성되지 않았습니다.",
  'snow.note.ponding': "지붕 경사가 1.2° 미만입니다. 고임 불안정을 검토해야 하며 (11장), 여기서는 계산하지 않습니다.",
  'snow.note.notCovered': "분담폭을 사용하면 부분 하중 (5장), 드리프트 (7장과 8장), 미끄러지는 눈 (9장)은 생성되지 않으며 패널에서 읽어냅니다. 얼음 댐 (§4.5)도 마찬가지입니다.",
  'wind.other.kind': "구조물",
