  'spec.variable.hint': "각 지점의 성질은 숫자의 평균이 아니라 그 위치의 단면 성질입니다. 해석은 부재를 일정 단면 조각으로 나누고 하나의 부재로 보고합니다. 열두 조각이면 처짐이 정확한 값의 0.5 % 이내로 유지됩니다. 설계는 이를 검토하지 않습니다. 변단면 부재에는 별도의 방법이 필요합니다.",
  'spec.variable.mode.outline': "윤곽 변환, 꼭짓점별: 두 단면의 구성이 같습니다.",
