  'spec.axial.cable': "케이블",
  'spec.axial.cableHint': "케이블은 인장만 받으며, 자중으로 강성이 줄어들고 (Ernst 등가 탄성계수) 처짐이 생깁니다. 결과에는 장력, 수평 추력, 처짐, 탄성계수가 표시됩니다. 무응력 길이는 프리텐션을 지정하지 않으면 현의 길이입니다. 프리텐션은 그려진 현에서 자중을 받을 때의 장력입니다.",
