  'cableDiag.selfWeight': "이 케이블들의 장력 중 최대 {pct} %는 그려진 현을 무응력 길이로 한 자중에서 오며, 하중과 관계없이 팽팽하게 유지됩니다. 각 케이블의 프리텐션을 지정하거나 (사양 › 부재), 케이블이 아니라면 트러스 부재로 바꾸십시오.",
  'plasticDiag.noCapacity': "소성 해석이 거부되었습니다. 부재 {member} (단면 {section})에 적어도 한 축에 대해 유한한 양의 소성모멘트가 없으며, 어느 축이든 용량이 없거나 유효하지 않으면 신뢰할 수 있는 소성 해석이 불가능합니다. 단면 치수, 0보다 큰 항복강도, 또는 양의 Mp 값을 지정하십시오.",
