  'adv.harmonicExcitation': "가진은 모델의 모든 하중을 계수 없이 합한 것이며, 스윕하는 진동수의 조화력으로 작용합니다. 곡선은 선택한 절점과 방향의 변위 진폭을 나타냅니다.",
  'adv.harmonicSlave': "절점 {node}은(는) {dir} 방향에서 다이어프램을 따릅니다. 그 방향의 응답은 주절점 {master}이(가) 결정합니다. 다른 절점을 선택하거나 Z 방향을 선택하십시오.",
  'adv.pushoverNotSteel': "푸시오버는 Mp = fy·Zp로 힌지를 형성하며, 이는 강재에만 성립합니다. 다음 부재는 다른 재료입니다: {names}. 실행하려면 제거하거나 재료를 변경하십시오.",
  'adv.pushoverAtZero': "구조물이 하중 이전에 이미 메커니즘입니다. λc = 0은 구속이 빠졌음을 나타냅니다.",
  'adv.imperfNotional': "가상하중 합계: {h} kN, 수직하중 {v} kN의 {pct} %이며, 각 절점이 지지하는 하중에 비례하여 절점에 분배됩니다.",
