  'adv.stageCases': "이 단계의 하중 케이스",
  'adv.stagedLaterMembers': "변위는 단계에 걸쳐 누적됩니다. 첫 단계 이후에 추가된 부재의 부재력과 반력에는 현재로서는 그 부재가 놓이기 전에 구조물이 가졌던 변형이 포함되므로 근사값으로 읽으십시오.",
  'adv.stagedNoCurvedShells': "곡면 쉘은 단계에 포함할 수 없습니다. 평판으로 바꾸거나 선형 해석을 실행하십시오.",
  'adv.stagedNoConnectors': "절점 사이의 커넥터는 단계에 포함할 수 없습니다. 제거하거나 선형 해석을 실행하십시오.",
  'adv.creepRH': "RH (%)",
  'adv.creepBasis': "EN 1992-1-1, Annex B: fcm = f'c + 8 MPa. 각 콘크리트는 자체 f'c를 사용하며, 여기의 값은 f'c가 없는 콘크리트에만 적용됩니다. 하중은 E/(1 + φ), 수축은 E/(1 + 0.8·φ)로 해석하며, 강재는 크리프도 수축도 일어나지 않습니다.",
  'adv.creepNoConcrete': "모델에 콘크리트가 없습니다. 크리프와 수축은 콘크리트의 성질입니다.",
  'adv.sectionJ': "J (Saint-Venant)",
