  'wb.conv.cables': "케이블: 케이블로 지정된 부재의 장력, 수평 추력, 자중에 의한 처짐, 해석에 사용한 등가(Ernst) 탄성계수. 느슨한 케이블은 0으로 표시됩니다.",
