  'cad.assume.cantilevers': "캔틸레버 슬래브(발코니) {n}개 (보 또는 인접 슬래브로 한 변만 지지되고 외부 기둥 없음)를 쉘 캔틸레버로 모델링했습니다. 지지되는 변은 인접한 보와 절점을 공유합니다 (보를 쉘 가장자리 절점에서 분할).",
