  'loads.cirsoc102.gust.noModalFrequency': "고유치 해석에서 {axis} 방향 질량을 갖는 모드가 나오지 않았습니다. 해당 방향의 n₁이 없습니다.",
  'loads.cirsoc102.gust.noTypedFrequency': "{axis} 방향의 n₁이 없습니다.",
  'loads.cirsoc102.gust.approxNotBuilding': "§1.9.3의 근사 진동수는 강재, 콘크리트 또는 조적조 건물에 해당합니다(§1.9.2.1). 굴뚝, 탑, 간판은 고유치 해석이 필요하거나 n₁을 직접 입력해야 합니다.",
  'loads.cirsoc102.gust.approxSensitive': "해설 C 1.1.2의 조건 중 하나에 해당합니다. 동적 응답에는 §1.9.3의 높이 기반 근사값이 아니라 해석으로 구한 진동수가 필요합니다. 고유치 해석을 사용하거나 n₁을 직접 입력하십시오.",
  'loads.cirsoc102.gust.weakModalMass': "{axis} 방향 질량의 10분의 1을 분담하는 모드가 없습니다. n₁은 모드 {mode}에서 취했으며 질량의 {mass} %를 분담합니다. 계산한 모드 수가 충분한지 확인하십시오.",
  'loads.cirsoc102.gust.torsionalFirstMode': "1차 모드({mode}, {f} Hz)는 거의 순수한 비틀림 모드입니다. 이 증폭은 G_f의 범위를 벗어나므로(해설 C 1.9) 공인된 문헌이나 풍동 시험이 필요합니다.",
  'loads.cirsoc102.gust.sensitive.tall': "h = {h} m가 120 m를 초과합니다. 풍직각 방향 및 공탄성 효과를 검토해야 합니다(해설 C 1.1.2, §2.1.3 및 §6.1).",
  'loads.cirsoc102.gust.sensitive.slender': "h = {h} m가 최소 유효 폭 B_min({b} m)의 4배를 초과합니다. 풍직각 방향 효과를 검토해야 합니다(해설 C 1.1.2).",
  'loads.cirsoc102.gust.sensitive.lowFrequency': "n₁ = {n1} Hz가 0.25 Hz 미만입니다. 풍직각 방향 및 공탄성 효과를 검토해야 합니다(해설 C 1.1.2).",
  'loads.cirsoc102.gust.sensitive.reducedSpeed': "환산 풍속 V̄/(n₁·B_min) = {v}이(가) 5를 초과합니다. 와류 방출을 검토해야 합니다(해설 C 1.1.2).",
