  'certificate.e2eTooltip': "독립 검증기가 모델의 데이터로부터 강성과 하중을 다시 구성했습니다(자체 요소 공식, 구간 연산 사용). 엔진의 조립 결과가 이와 일치하며, 이 한계는 기술된 그대로의 모델의 정확해에 대해 성립합니다.",
  'certificate.pending': "인증 중…",
  'certificate.tooltip': "Lean으로 증명한 엄밀한 사후 한계: 조립된 선형 연립방정식의 정확해는 계산된 변위와 최대 이 값만큼 차이가 납니다(모든 자유도에 대한 유클리드 노름, 미터와 라디안을 함께 사용). 부재력 옆의 ±는 같은 방식으로 그 오차의 한계를 나타냅니다.",
  'discretization.tooltip': "서로 다른 두 가지 오차입니다. 대수 오차(인증됨)는 계산된 변위가 조립된 유한요소 연립방정식의 정확해에서 얼마나 떨어져 있는지를 나타내는 엄밀한 한계입니다. 이산화 오차(추정)는 그 연립방정식이 메쉬가 나타내는 구조물에서 얼마나 떨어져 있는지를 나타냅니다. 메쉬에 따라 달라지며, 에너지 노름(막 및 휨)에서 Zienkiewicz–Zhu 응력 복원으로 추정하고, 인증되지 않습니다.",
