  'certificate.certifiedAbs': "인증됨: 변위 오차 ≤ {abs}",
  'certificate.envelopeCertified': "포락선 인증됨: 모든 값이 정확한 포락선의 {abs} 이내(변위)",
  'certificate.comboTooltip': "Lean으로 증명한 엄밀한 한계: 각 하중 케이스는 조립된 연립방정식의 정확해에 대해 인증되며, 하중조합의 한계는 케이스들의 한계에 |계수|를 곱한 값과 하중조합 자체의 반올림 오차를 더한 것입니다. 포락선은 정확한 포락선에서 가장 큰 하중조합 한계 이내에 있습니다. 부재력 옆의 ±는 같은 방식으로 그 오차의 한계를 나타냅니다.",
  'certificate.download': "인증서 다운로드",
  'certificate.bundleTooltip': "이 해석의 인증서 묶음을 다운로드합니다(JSON, 모든 수치를 정확하게 기록). 누구나 이 앱을 신뢰하지 않고 Lean 검증기로 독립적으로 다시 확인할 수 있습니다: lake exe certcheck <file>.",
  'certificate.bundleFailed': "인증서를 내보낼 수 없었습니다: {reason}",
  'certificate.shellTooltip': "이 합력의 오차에 대한 인증된 한계: 조립된 연립방정식의 정확해는 표시된 값의 ± 이 값 이내입니다.",
  'certificate.atPoint': "정확한 값은 ± {b} 이내(인증됨)",
  'certificate.modal': "모드 {n}개의 ω²를 구간으로 포함함(인증됨)",
  'certificate.modalComplete': "{f} Hz 미만에서 누락된 모드 없음(모드 {n}개)",
  'certificate.modalIncomplete': "완전성 인증되지 않음: {reason}",
  'certificate.modalMode': "모드 {i}: f ∈ {range} Hz",
  'certificate.modalAll': "인증된 진동수 구간",
  'certificate.modalTooltip': "엄밀한 포함 구간: 계산된 각 진동수의 정확한 값은 그 구간 안에 있으며, 계산된 모드는 차단 진동수 아래의 모든 모드로 누락이 없습니다(Lean으로 증명한 정리이며, 강성-질량 쌍으로의 변수 변환은 형식화되지 않았습니다).",
  'certificate.pdeltaStable': "2차 상태 안정함이 인증됨",
  'certificate.pdeltaStabilityUnknown': "안정성 인증되지 않음",
  'certificate.pdeltaTooltip': "Newton–Kantorovich 인증서: 정확한 P-Δ 평형이 존재하며, 계산된 평형 근처에서 유일하고, 계산된 변위와 최대 이 값만큼 차이가 납니다(모든 자유도에 대한 유클리드 노름). 안정: 정확한 2차 강성이 양의 정부호임이 인증됩니다. Lean으로 형식화되지 않았습니다.",
  'certificate.spectral': "인증됨: Vb ∈ {vb} kN · 변위 오차 ≤ {du} · 부재력 오차 ≤ {df}",
  'certificate.spectralTooltip': "정확한 최저차 모드의 SRSS/CQC 응답에 대한 엄밀한 포함 구간: 정확한 밑면 전단력은 구간 안에 있고, 보고된 모든 변위와 부재력은 정확한 값의 한계 이내입니다. Lean으로 형식화되지 않았습니다.",
  'certificate.harmonicMethod': "방법: {method}",
  'certificate.harmonicModes': "{dof}자유도 중 모드 {n}개",
  'certificate.harmonicTruncation': "생략된 모드가 정적 응답의 {pct}%를 분담합니다",
  'certificate.harmonic': "인증됨: 최대 진폭 ∈ {peak} · 보고된 오차 ≤ {err}",
  'certificate.harmonicTooltip': "계산된 모든 진동수에서 응답 자유도에 대한 Rayleigh 감쇠 모델의 정확한 정상상태 응답의 엄밀한 포함 구간: 정확한 최대 진폭은 구간 안에 있고, 모드 절단을 포함하여 보고된 모든 값은 정확한 값의 한계 이내입니다. 위상은 한계가 정해지지 않았습니다. Lean으로 형식화되지 않았습니다.",
  'certificate.thStableUpTo': "수치 기법 안정함이 인증됨(Δt ≤ {dt} s)",
